        (0 until n).foreach { i => 
            readLine.split(" ").map(_.toInt).toList match {
                case src :: d :: dst => g.add(src, dst);
                case _ => ()
            }
        }
        g.depthFirstSearch.zipWithIndex.foreach { e => e match {
                case ((discover, finish), node) => println("%d %d %d".format(node + 1, discover, finish));
            }
        }
