class AdjacentListGraph[A](val size: Int) {
    val al = scala.collection.mutable.HashMap[A, List[A]]();

    def dump = al.toList.foreach { e => println("%d -> %s".format(e._1, e._2.mkString(" ")))}

    def add(src: A, dst: A): Unit = {
        al.put(src, dst :: al.getOrElse(src, Nil));
        al.put(dst, src :: al.getOrElse(dst, Nil));
    }
    def bfs(src: A, dst: A): Boolean = {
        val vMap = scala.collection.mutable.HashMap[A, Int]();
        val que = new Queue[A](size);
        @tailrec
        def _bfs(): Boolean = que.deque match { // 幅優先での探索
            case None => false;
            case Some(curr) => {
                val exists = al.getOrElse(curr, Nil).
                    filterNot(vMap.isDefinedAt(_)).
                    find { child => if (child == dst) {
                            true
                        } else {
                            que.enque(child);
                            vMap.put(child, 1);
                            false;
                        } 
                    }
                if (exists == None) _bfs() else true;
            }
        }
        que.enque(src);
        vMap.put(src, 1);
        if (src == dst) true else _bfs();
    }
}
class Queue[A](size: Int){
    var inPtr = 0;
    var outPtr = 0;
    var cnt = 0;
    val q = new scala.collection.mutable.ArraySeq[A](size)

    def isEmpty: Boolean = cnt == 0;

    def isFull: Boolean = cnt == size;

    def enque(elem: A): Boolean = if (isFull) false else {
        q(inPtr) = elem;
        inPtr = if (inPtr == (size - 1)) 0 else inPtr + 1;
        cnt += 1;
        true;
    }

    def deque(): Option[A] = if (isEmpty) None else {
        val elem = q(outPtr);
        outPtr = if (outPtr == size - 1) 0 else outPtr + 1;
        cnt -= 1;
        Some(elem);
    }
}

