class IntGraph(size: Int) {
    val matrix: Array[List[Int]] = new Array[List[Int]](size).map( e => Nil);
    val cList = new Array[Int](size).map( e => -1);
    def add(src: Int, dst: Int): Unit = {
        matrix(src) = dst :: matrix(src);
        matrix(dst) = src :: matrix(dst);
    }

    def buildConnectionList(): Unit = {
        def _buildConnectionList(que: Queue[Int], group: Int): Queue[Int] = {
            que.dequeueOption match {
                case None => que;
                case Some((src, restQue)) => {
                    val newQue = matrix(src).filter(dst => cList(dst) == -1).foldLeft(restQue) { (tmpQue, dst) =>
                        cList(dst) = group;
                        tmpQue.enqueue(dst);
                    }
                    _buildConnectionList(newQue, group);
                }
            }
        }
        (0 until size).foldLeft(0) { (group, i) =>
            if (cList(i) == -1) {
                cList(i) = group;
                _buildConnectionList(Queue[Int](i), group);
                group + 1;
            } else {
                group;
            }
        }
    }

    def connected(src: Int, dst: Int): Boolean = cList(src) == cList(dst);
}

