class AdjacentListGraph(val size: Int) {
    val al = new Array[List[Int]](size);

    def dump = al.zipWithIndex.filterNot(a => a._1 == null).foreach { e => println("%d -> %s".format(e._2, e._1.mkString(" ")))}
