#include <bits/stdc++.h>
using namespace std;

#define NIL -1

typedef vector<int> Adj_list;
typedef vector<Adj_list> Adj_lists;
typedef vector<int> Group_ids;

void set_group_ids(const Adj_lists& adj_lists, Group_ids& group_ids){

  int id = -1;
  for(int i=0; i<adj_lists.size(); i++){
    if(group_ids.at(i) != NIL) continue;
    else id++;

    queue<int> q;
    q.push(i);

    while(!q.empty()){
      // visit top of queue
      const int& visit = q.front();
      const Adj_list& adj_list = adj_lists.at(visit);

      // push adjecent node which is not visited yet
      for(const int& adj : adj_list){
        if(group_ids.at(adj) == NIL){
          q.push(adj);
        }
      }

      group_ids.at(visit) = id;
      q.pop();
    }
  }
}

int main(){

  int n, m;
  scanf("%d %d", &n, &m);

  Adj_lists adj_lists(n);
  for(int i=0; i<m; i++){
    int a, b;
    scanf("%d %d", &a, &b);
    adj_lists.at(a).push_back(b);
    adj_lists.at(b).push_back(a);
  }

  Group_ids group_ids(n+1, NIL);
  set_group_ids(adj_lists, group_ids);

  int q;
  scanf("%d", &q);
  for(int i=0; i<q; i++){
    int a, b;
    scanf("%d %d", &a, &b);
    if(group_ids.at(a) == group_ids.at(b)) printf("yes\n");
    else printf("no\n");
  }

  return 0;
}

