class Vtx {
public:
	int id;
	int color=-1;
	vector<int> vtxs;
	void add(int x){
		vtxs.push_back(x);
	}
};

void dfs(int color,int id, Vtx vtxs[]){
	stack<int> stack;
	stack.push(id);
	while(!stack.empty()){
		id=stack.top(); stack.pop();
		if(vtxs[id].color==-1){
			vtxs[id].color=color;
		}
		int size=vtxs[id].vtxs.size();
		for(int i=0;i<size;i++){
			int nId=vtxs[id].vtxs[i];
			if(vtxs[nId].color==-1){
				stack.push(nId);
			}
		}
	}
}

void assignColor(int n, Vtx vtxs[]){
	int color=0;
	for(int i=0;i<n;i++){
		if(vtxs[i].color==-1){
			dfs(color,i,vtxs);
			color++;
		}
	}
}

