		scanf("%d %d", &s, &t);

		int ps = parent(table, s);
		int pt = parent(table, t);
		if (ps != pt) {
			table[ps] = pt;
		}
	}

	scanf("%d", &q);

	for (int i = 0; i < q; i++) {
		int s, t;

		scanf("%d %d", &s, &t);

		int ps = parent(table, s);
		int pt = parent(table, t);

