};

struct memo {
	int a, b;
	bool val;
	bool operator==(memo m){
		return (this->a == m.a && this->b == m.b) || (this->a == m.b && this->b == m.a);
	}
};

int n, m, q;
node* nodes;
vector<memo> ms;

bool canReach(int s, int d, bool* h){
    h[s] = true;
	if(s==d) return true;

	memo nm;
	nm.a = s;
	nm.b = d;

	vector<memo>::iterator it = find(ms.begin(), ms.end(), nm);
	if(it != ms.end()) return (*it).val;

    for(int i = 0; i < nodes[s].rel.size(); i++){
		if(!h[nodes[s].rel[i]] && canReach(nodes[s].rel[i], d, h)){
			nm.val = true;
			ms.push_back(nm);
			return true;
        }
    }

	nm.val = false;
	ms.push_back(nm);
    return false;
}

