#include<iostream>
#include<list>
#include<iterator>
#define MAX 100000
using namespace std;
char ans[MAX + 1];

class person
{
public:
	int id;
	bool Isdone = false;
	list <person*> lis;
	bool serch(person* Per)
	{
		if (ans[Per->id] == 1)return true;
		else if (ans[Per->id] == -1)return false;
		Isdone = true;
		for(list<person*>::iterator temp=lis.begin();temp!=lis.end();++temp)
		{
			if ((*temp) == Per)
			{
				ans[(*temp)->id] = 1;
				return true;
			}
			else if ((*temp)->Isdone == true)continue;
			else
			{
				if ((*temp)->serch(Per))
				{
					ans[(*temp)->id] = 1;
					return true;
				}
			}
		}
		ans[Per->id] = -1;
		return false;
	}
};

person P[MAX + 1];

int main()
{
	int n, m;
	cin >> n >> m;
	for (int i = 0; i < n; i++)P[i].id = i;
	for (int i = 0; i < m; i++)
	{
		int p1, p2;
		scanf("%d%d",&p1, &p2);
		P[p1].lis.push_back(&P[p2]);
		P[p2].lis.push_back(&P[p1]);
	}			 
	int q;
	cin >> q;
	for (int i = 0; i < q; i++)
	{
		int p1, p2;
		scanf("%d%d", &p1, &p2);
		if (P[p1].serch(&P[p2]))
		{
			cout << "yes" << endl;
		}
		else
		{
			cout << "no" << endl;
		}
		for (int l = 0; l < n; l++)P[l].Isdone = false;
		for (int l = 0; l < n; l++)ans[l] = 0;
	}
	return 0;
}

