void find_route(int s) {
  queue<int> S;

  S.push(s);
  color[s] = GRAY;

  reach[s] = s;

  while(!S.empty()){
    int v = S.front(); S.pop();

    for (int i = 0; i < (int)G[v].size(); i++) {
