using Graph = std::vector<std::vector<uint32_t>>;

void dfs(const Graph& G, uint32_t start, std::vector<uint32_t>& group,
         uint32_t mark) {
  group[start] = mark;
  for (auto&& g : G[start]) {
    if (group[g] == mark) continue;
    dfs(G, g, group, mark);
  }
  return;
}

