void dfs(int in, int color,
    const vector<vector<int>>& graph,
    vector<int>& colors) 
{
    vector<bool> checkList(colors.size());
    stack<int> stack;
    stack.push(in);
    colors[in] = color;

    while (!stack.empty())
    {
        int x = stack.top();
        bool canLeave = true;
        for (const auto& g : graph[x]) {
            if (colors[g] == 0) {
                stack.push(g);
                colors[g] = color;
                checkList[g] = true;
                canLeave = false;
            }
        }
        if (canLeave) {
            stack.pop();
        }
    }
}

void wfs(int in, int color,
    const vector<vector<int>>& graph,
    vector<int>& colors)
{
    queue<int> queue;
    queue.push(in);
    vector<bool> checkList(colors.size());
    while (!queue.empty()) 
    {
        int x = queue.front();
        queue.pop();
        colors[x] = color;
        for (auto y : graph[x]) {
            if (!checkList[y]) {
                queue.push(y);
                checkList[y] = true;
            }
        }
    }
}

