void dfs(int r, int c) {
	int i, u, v;
	stack<int> s;
	s.push(r);
	grp[r] = c;
	while (!s.empty()) {
		u = s.top();
		s.pop();
		for (i = 0; i < ver[u].size(); i++) {
			v = ver[u][i];
			if (grp[v] == NIL) {
				grp[v] = c;
				s.push(v);
			}
