#include <iostream>
#include <vector>
#include <algorithm>
#include <deque>
using namespace std;

struct status{
    int id;
    vector<int> children{};
    int visited = 0;

    void resetVisited(){
        this->visited = 0;
    }
};

deque<int> schedule; 
vector<status> graph;

bool bfs(int target_v){
    if (schedule.empty()){
        return false;
    }

    int now_v = schedule.front();
    schedule.pop_front();

    for(auto& next_v:graph[now_v].children){
        if(graph[next_v].visited) continue;

        if(next_v==target_v) return true;
        graph[next_v].visited = 1;
        schedule.push_back(next_v);
    }
    return bfs(target_v);
}


int main(void){cin.tie(0);ios::sync_with_stdio(false);

    //setup
    int nb_v; cin >> nb_v;
    int nb_e; cin >> nb_e;
    graph.resize(nb_v);
    for(int i=0; i<nb_e; ++i){
        int v1, v2; cin >> v1 >> v2;
        graph[v1].children.push_back(v2);
        graph[v2].children.push_back(v1);
    }
    for(auto& a:graph){
        sort(a.children.begin(),a.children.end());
    }

    //bfs
    int times; cin>>times;
    for(int i=0; i<times; ++i){
        int from_v; cin>>from_v;
        int to_v; cin>>to_v;
        for(auto& a:graph) a.resetVisited();
        schedule = {};
        schedule.push_back(from_v);
        cout<<(bfs(to_v)? "yes\n":"no\n");
    }
}

