using namespace std;

struct UnionFind {
    vector<int> parent;

    // Constructor
    UnionFind(int n) {
        parent.resize(n);
        rep(i, n) parent[i] = i;
    }

    // 親を取得
    int root(int x) {
        if (parent[x] == x) {
            return x;
        } else {
            parent[x] = root(parent[x]);
            return parent[x];
        }
    }

    // 二つのデータを同じ木にくっつける
    void connect(int x, int y) {
        int rx = root(x);
        int ry = root(y);

        if (rx == ry) return; // 元から同じ木に属する場合は何もしない
        parent[rx] = ry;
    }

    // 二つのデータが同じ木に属するか判定
    bool check(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
    int n, m; cin >> n >> m;
    UnionFind tree(n);
    rep(i, m) {
        int s, t; cin >> s >> t;
        tree.connect(s, t);
    }
    int q; cin >> q;
    rep(i, q) {
        int s, t; cin >> s >> t;
        cout << (tree.check(s, t) ? "yes" : "no") << endl;
    }
}

