std::queue<int> q;
typedef struct{
	bool isVisited;
	std::vector<int> neighbors;
} node;

void bfs(node* nodes, int t){
	int id;
	while (!q.empty()){
		id = q.front();
		q.pop();
		if (!nodes[t].isVisited){
			for (int i=0; i<nodes[id].neighbors.size(); i++){
				if (!nodes[nodes[id].neighbors[i]].isVisited){
					q.push(nodes[id].neighbors[i]);
					nodes[nodes[id].neighbors[i]].isVisited=true;
				}
			}
		}
	}
	if (nodes[t].isVisited) printf("yes\n");
	else printf("no\n");
}

int main(){
	int n, d, num_relation, n_query, s, t;
	node *nodes;

	scanf("%d %d", &n, &num_relation);
	nodes = new node[n];
	for(int i=0;i<num_relation;i++){
		scanf("%d %d", &s, &t);
		nodes[s].neighbors.push_back(t);
		nodes[t].neighbors.push_back(s);
	}

	scanf("%d", &n_query);
	for(int i=0;i<n_query;i++){
		for (int j=0; j<n;j++){
			nodes[j].isVisited=false;
		}
		scanf("%d %d", &s, &t);
		q.push(s);
		bfs(nodes, t);
	}

	delete []nodes;
	return 0;
}

