using namespace std;

struct Node {
  vector<int> friends;
  int depth;
};
vector<Node> nodes;


void bfs(int id) {
  queue<int> q;
  q.push(id);

  for (auto el : nodes) {
    el.depth = -1;
  }
  nodes[id].depth = 0;

  while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (auto fid : nodes[u].friends) {
      if (nodes[fid].depth <= 0) {
        q.push(fid);
        nodes[fid].depth = nodes[u].depth + 1;
      }
    }
  }
}

bool isAccessible(int id){
  return (nodes[id].depth > 0);
}


