void breadthFirstSearch(int first, int id)
{
    std::deque<int> dq;
    assert(color[first] == -1);

    dq.push_back(first);
    color[first] = id;

    while (! dq.empty())
    {
        int current = dq.front();
        dq.pop_front();

        for (std::vector<int>::iterator it = connection[current].begin(); it != connection[current].end(); ++it)
        {
            if (color[(*it)] > -1)
