const int INF = 1'000'000'007;
const ll MOD = 998'244'353;

vi par, dep, siz;
int root(int x) {
	if (par[x] == x) return x;
	else return par[x] = root(par[x]);
}
void unite(int x, int y) {
	x = root(x); y = root(y);
	if (x == y) return;
	if (dep[x] > dep[y]) { par[y] = x; siz[x] += siz[y]; }
	else if (dep[x] < dep[y]) { par[x] = y; siz[y] += siz[x]; }
	else { par[y] = x; dep[x] ++; siz[x] += siz[y]; }
}
bool same(int x, int y) { return root(x) == root(y); }
void uf(int NODENUM) {
	par.assign(NODENUM, 0); dep.assign(NODENUM, 0); siz.assign(NODENUM, 1);
	rep(i, NODENUM) par[i] = i;
}

