using namespace std;

struct status{
    int id;
    vector<int> children{};
    int visited = 0;
    int depth = -1;
};

deque<int> schedule; 
vector<status> graph;

bool bfs(int target_v){
    if (not schedule.empty()){

        int now_v = schedule.front();
        schedule.pop_front();
        if(now_v==target_v) return true;

        for(auto& next_v:graph[now_v].children){
            if(graph[next_v].visited) continue;

            graph[next_v].visited = 1;
            schedule.push_back(next_v);
        }
        return bfs(target_v);
    }
    return false;
}

