#include <unordered_set>
#include <algorithm>
//#include "../cxx-prettyprint/prettyprint.hpp"

std::vector<std::vector<int>> Adj;
std::unordered_set<int> nodes_visited;

bool is_reachable(int s, int t) {
    if (std::find(Adj[s].begin(), Adj[s].end(), t) != Adj[s].end()) {
        return true;
    } else if (nodes_visited.find(s) != nodes_visited.end()) {
        return false;
    } else {
        nodes_visited.insert(s);
        bool value = std::any_of(Adj[s].begin(), Adj[s].end(),
                                 [&](int next){return is_reachable(next, t);});
        return value;
    }
}

