int rank[maxn];
void init(int n)
{
   for(int i=0;i<n;i++)
   {
       p[i]=i;
       rank[i]=0;
   }
}
int fnd(int x)
{
    int y=x;
    if(x==p[x]) return x;
    while(x!=p[x])
    {
        x=p[x];
    }
    return p[y]=x;
}
bool is_same(int x,int y)
{
   return fnd(x)==fnd(y);
}

void uni(int x,int y)
{
   x=fnd(x);
   y=fnd(y);
   if(rank[x]>rank[y])
   {
       p[y]=x;
       rank[y]++;
   }
   else
   {
       p[x]=y;
       rank[x]++;
   }
}

