int find(node x, vector<int> path){
    if(x.parent == -1){
        REP(i, path.size())
            person[path[i]].parent = x.id;
        return x.id;
    }
    else{
        path.push_back(x.id);
        return find(person[x.parent], path);
    }
}

void marge(node x, node y){
    vector<int> xpath, ypath;
    int x_id = find(x, xpath);
    int y_id = find(y, ypath);
    if(x_id == y_id)
        return;
    else
        person[y_id].parent = x_id;
    return;
}

bool judge(node x, node y){
    vector<int> xpath, ypath;
    return find(x, xpath) == find(y, ypath);
}

