    rep(i,q){
        int x,y; cin >> x >> y;
        if(tree.find(x) != -1 && tree.find(y) != -1){
            if(tree.find(x) == tree.find(y)) cout << "yes" << endl;
            else cout << "no" << endl;
        }else cout << "no" << endl;
    }
}

