vector<int> visit;

bool bfs(int s, int t, vector<vector<int>> list) {
  if (s == t) {
    return true;
  }

  // visit flag
  visit[s] = 1;

  for (int i = 0; i < list[s].size(); i++) {
    int next = list[s][i];
    if (visit[next] == 0) {
      if (bfs(next, t, list)) {
        return true;
      }
    }
  }
  return false;
}

