void bfs(vector<vector<int>> &sns, vector<int> &color, int x)
{
    if (color[x] != -1 || sns[x].empty()) return;
    queue<int> mq;
    mq.push(x);
    while(!mq.empty()) {
        int curr = mq.front();
        mq.pop();
        color[curr] = x;
        for (int i = 0; i < sns[curr].size(); i++) {
            int next = sns[curr][i];
            if (color[next] == -1) {
                mq.push(next);
                color[next] = x;
            }
        }
    }
}

void assignColor(vector<vector<int>> &sns, vector<int> &color)
{
    for (int i = 0; i < sns.size(); i++) {
        bfs(sns, color, i);
    }
}

