	Node(int id, int n);
	~Node(){ delete[] friends; }
	void addFriend(Node *friend_node);
	bool searchFriend(int id);
};

Node::Node(int id, int n)
{
	this->id = id;
	friend_num = 0;
	friends = new Node*[n];
	check_id = -1;
}

void Node::addFriend(Node *friend_node)
{
	friends[friend_num] = friend_node;
	friend_num++;
}

bool Node::searchFriend(int id)
{
	if (check_id == id) return false;
	check_id = id;

	if (this->id == id) {
		check_id = -1;
		return true;
	}

	for (int i = 0; i < friend_num; i++) {
		if (friends[i]->searchFriend(id)) {
			check_id = -1;
			return true;
		}
	}
	check_id = -1;
	return false;
}

