#include<bits/stdc++.h>
using namespace std;
#define int long long

const int N = 1e5+10;
int par[N]; //親
int depth[N]; //木の深さ

struct UF{

  void init(int n){
    for(int i = 0; i < n; i++){
      par[i] = i;
      depth[i] = 0;
    }
  }

  //木の根を求める
  int root(int x){
    if(par[x] == x){
      return x;
    }
    else {
      return par[x] = root(par[x]);
    }
  }

  //xとyの属する集合を併合
  void unite(int x,int y){
    x = root(x);
    y = root(y);
    if(x == y) return;

    if(depth[x] < depth[y]) par[x] = y;
    else {
      par[y] = x;
      if(depth[x] == depth[y]) depth[x]++;
    }
  }
}uf;

signed main(){
  cin.tie(0);
