    uf.unite(x,y);
  }

  int q; cin >> q;
  for(int i = 0; i < q; i++){
    int x,y; cin >> x >> y;
    if(uf.root(x) == uf.root(y)){
      cout << "yes" << endl;
    }
    else {
      cout << "no" << endl;
    }
  }

  return 0;
}

