//深さ優先探索を行う
void dfs(int r, int c){

    //スタックを作る
    stack<int> S;

    //スタックに初期頂点を入れる
    S.push(r);

    //color(ID)を初期頂点に代入する
    color[r] = c;


    //スタックが空でない限り行う
    //rと同じIDを入れ続ける
    while(!S.empty()){

        //スタックの一番上を取り出す
        int u = S.top();S.pop();

        //頂点uにつながっている頂点の数だけ繰り返す
        for(int i=0;i<G[u].size();i++){

            //uにつながっている頂点vを取り出す
            int v = G[u][i];

            //もしvがまだIDが決まっていなかったら
            //まだ何も頂点vが触られていなかったら
            //これがないと永遠にループする
            if(color[v] == NIL){

                //color[v]に同じIDを代入する
                color[v] = c;

                //スタックにvを追加する
                S.push(v);
            }
        }
    }
}

