    //頂点分繰り返す
    for(int u=0;u<n;u++){

        //もし、ある頂点uのIDがまだ決まっていなかったら
        if(color[u] == NIL){

            //深さ優先探索を行う
            dfs(u, id++);
        }
    }
}

