        int s;
        int t;
        std::scanf("%d", &s);
        std::scanf("%d", &t);
        bool find = false;
        for(int j = 0; j < rCount; ++j){
            if(relations[j].find(s) != relations[j].end()){
                if(relations[j].find(t) == relations[j].end()){
                    relations[j].insert(t);
                }
                find = true;
                break;
            } else if(relations[j].find(t) != relations[j].end()){
                if(relations[j].find(s) == relations[j].end()){
                    relations[j].insert(s);
                }
                find = true;
                break;
            }
        }
        if(find == false){
            relations[rCount].insert(s);
            relations[rCount].insert(t);
            ++rCount;
        }
