using namespace std;

bool isReachable(int k, int l, vector<vector<int> > node) {
	int n=(int)node.size();
	int i;
	int m;
	queue<int> qnode;
	vector<int> visited;
	visited.resize(n);
	for(i=0; i<n; ++i) {
		visited[i]=0;
	}
	visited[k]=1;
	qnode.push(k);
	while(!qnode.empty()) {
		m=qnode.front();
		for(i=0; i<(int)node[m].size(); ++i) {
			if(node[m][i]==l) {
				return true;
			} else {
				if(visited[node[m][i]]==0) {
					qnode.push(node[m][i]);
					visited[node[m][i]]=1;
				}
			}
		}
		qnode.pop();
	}
	return false;
}

int main() {
	int m,n,k,l;
	int q;
	int i;
	vector<vector<int> > node;
	scanf("%d%d",&n,&m);
	node.resize(n);
	for(i=0; i<m; ++i) {
		scanf("%d%d",&k,&l);
		node[k].push_back(l);
		node[l].push_back(k);
	}
	scanf("%d",&q);
	for(i=0; i<q; ++i) {
		scanf("%d%d",&k,&l);
		printf((isReachable(k,l,node)?"yes\n":"no\n"));
	}
	return 0;
}

