bool DFS(const vector<set<int> >& G, int a, int b) {
    if (G[a].size() == 0) return false;

    stack<pair<int, set<int>::iterator> > S;
    vector<bool> is_visited(G.size(), false);

    set<int>::iterator idx = G[a].begin();
    do {
        if (idx == G[a].end()) {
            a   = S.top().first;
            idx = S.top().second;
            S.pop();
            idx++;
            continue;
        }
        if (*idx == b) return true;
        if (!is_visited[*idx]) {
            is_visited[*idx] = true;
            S.push(make_pair(a, idx));
            a   = *idx;
            idx = G[a].begin();
            continue;
        }
        idx++;
    } while (!S.empty());
    return false;
}


