typedef class unionfindtree{
private:
	std::vector<int> par,rank;
public:
	void init(int n){
		for(int i=0;i<n;i++){
			par.push_back(i);
			rank.push_back(0);
		}
	}
	int find(int x){
		if(par[x]==x) return x;
		return par[x]=find(par[x]);
	}
	bool same(int x,int y){
		if(find(x)==find(y)) return true;
		else return false;
	}
	void uni(int x,int y){
		x=find(x);
		y=find(y);
		if(rank[x]>=rank[y]){
			par[y]=x;
			rank[x]=rank[x]+1;
		}else if(rank[x]<rank[y]){
			par[x]=y;
			rank[y]=rank[y]+1;
		}
	}
}UFT;
