using namespace std;
int n, m;
struct node {
    int id;
    node* parent;
};

node find(node x){
    if(x.parent == NULL)
        return x;
    else
        x = find(*x.parent);
    return x;
}

void marge(node x, node y){
    x = find(x);
    y = find(y);
    if(x.id == y.id)
        return;
    else
        y.parent = &x;
    return;
}

bool judge(node x, node y){
    x = find(x);
    y = find(y);
    return x.id == y.id;
}

