	for (int i = 0; i < m; i++)
	{
		int a, b;
		cin >> a >> b;
		if (a > b) {
			swap(a, b);
		}
		//b→a
		tree.unite(a, b);

	}

	cin >> q;

	for (int i = 0; i < q; i++)
	{
		int a, b;
		cin >> a >> b;
		if (tree.same(a, b)) {
			cout << "yes" << endl;
		}
		else
		{
			cout << "no" << endl;
		}
	}


	return 0;
}

