vector< int > connections;

void addConnection(int a, int b) {
  if (connections[a] == a && connections[b] == b)
    a < b ? connections[b] = a : connections[a] = b;
  else if (connections[a] == a)
    addConnection(a, connections[b]);
  else if (connections[b] == b)
    addConnection(connections[a], b);
  else
    addConnection(connections[a], connections[b]);
}

bool checkConnection(int a, int b) {
  if (connections[a] == a && connections[b] == b) {
    if (a == b)
      return true;
    else
      return false;
  } else if (connections[a] == a) {
    return checkConnection(a, connections[b]);
  } else if (connections[b] == b) {
    return checkConnection(connections[a], b);
  } else
    return checkConnection(connections[a], connections[b]);
}

