void dfs_run(int a, int b, vector<vector<int>>& adj, vector<bool>& checker) {
	//cout << a << endl;
	if(frag == false) {
		while(!adj[a].empty()) {
			int tmp;
			tmp = adj[a].back();
			adj[a].pop_back();	
			if(checker[tmp] == false) {
				continue;
			}
			checker[tmp] = false;
			if(tmp == b) {
				frag = true;
			}else{
				dfs_run(tmp, b, adj, checker);
			}
		}
	}
}

