struct union_find{//rank,経路圧縮で高速化
  vi par;//parは添字の親（または自分が根の時自身）を示す。
  vi rank;//rankは木の高さ（根についてのみ実装）
  union_find(int n){
    par.assign(n,0);
    rank.assign(n,0);
    REP(i,n) par[i]=i;
  }
  int find(int a){//根を探す
    if(par[a]==a) return a;
    else return par[a] = find(par[a]);//根に直接つける
  }
  void unite(int a,int b){//小さい方の木の根に大きい方の根を上書きする
    int roota,rootb;
    roota = find(a),rootb = find(b);
    if(roota==rootb) return;
    if(rank[roota]>rank[rootb]){
      par[rootb] = roota;
    }else if(rank[roota]<rank[rootb]){
      par[roota] = rootb;
    }else{
      rank[roota]++;
      par[rootb] = roota;
    }
  }
};
