queue<int> queueBfs;


void assignColor() {
  queueBfs.push(0);
  color[0] = colorId;

  while (!queueBfs.empty()) {
    int front = queueBfs.front();

    int next = NIL;
    for (int i = 0; i < G[front].size(); i++) {
      if (color[G[front][i]] == NIL) {
        next = G[front][i];
        queueBfs.push(G[front][i]);
        color[G[front][i]] = colorId;
      }
    }
    queueBfs.pop();

    // NILになっている島を探す
    if (queueBfs.empty()) {
      for (int i = 0; i < n; i++) {
        if (color[i] == NIL) {
          queueBfs.push(i);
          colorId++;
          color[i] = colorId;
          break;
        }
      }
    }

  }
}

