struct UnionFind{
  using val_t=size_t;
  vector<val_t> par;
  explicit UnionFind(size_t n): par(n) {
    iota(begin(par),end(par),0);
  }
  void connect(val_t s, val_t t){
    // par[root(s)]=t;
    par[root(s)]=root(t);
  }
  val_t root(val_t s){
    if(par[s]!=s) par[s]=root(par[s]);
    return par[s];
  }
  bool visit(val_t s, val_t t){
    return root(s)==root(t);
  }
};
