struct Node{
    vector<int> fri;
    bool flag;
};
queue<Node> refresh(queue<Node> que,Node node[],int n){
    while(!que.empty())
        que.pop();

    for(int i=0; i<n; i++)
        node[i].flag=false;

    return que;
}

