class queue{
    int head;
    int tail;
    int size;
    int *q;
public:
    queue(int n){
        head=0;
        tail=0;
        size=n;
        q = (int *)malloc(sizeof(int)*size);
    }
    void push(int n){
        if(tail-head>=size){
            return;
        }
//        printf("%d in.\n",n);
        q[tail%size]=n;
        tail++;
    }
    int pop(){
        if(tail<=head){
            return -1;
        }
        head++;
        return q[(head-1)%size];
    }
};

bool isFriend(int s, int t,int n,char **f,int *kakunin,int c){
    bool hoge;
    int tmp;
    queue ob(n);
    ob.push(s);
    kakunin[s]=c;
    for(int i=0;i<n;i++){
        hoge = true;
        while(true){
            tmp = ob.pop();
            if(tmp==-1)return false;
            for(int j=0;j<n;j++){
                if(f[tmp][j]&&(kakunin[j]<c)){
                    ob.push(j);
                    kakunin[j] = c;
                    f[s][j] = 1;
                    hoge = false;
                    if(j==t)return true;
                }
            }
        }
        if(hoge)return false;
    }
    return false;
}

