class union_find {
  public:
    /// <param name="len">要素数</param>
    union_find(int len) {
      parents = new int[len];
      depths = new int[len];
      for (int i = 0; i < len; i++) parents[i] = i;
      memset(depths, 0, len);
    }
    /// 根を特定　あまり外部から使わない
    int root(int x) {
      return parents[x] == x ? x :
             root(parents[x]);
    }
    /// 2つの要素が同じ木に属すると宣言
    void unite(int x, int y) {
      x = root(x);
      y = root(y);
      if (x == y) return;
      if (depths[x] < depths[y]) parents[x] = y;
      else {
        parents[y] = x;
        if (depths[x] == depths[y]) depths[x]++;
      }
    }
    /// 同じ木に属するか
    bool same(int x, int y) {
      return root(x) == root(y);
    }
  private:
    int *parents;
    int *depths;
};

int main() {
  int n = IN, m = IN;
  union_find uf(n);
  rep(m) {
    uf.unite(IN, IN);
  }
  int q = IN;
  rep(q) OUT(uf.same(IN, IN) ? "yes" : "no");
}

