bool doublesearch(int st,int ed){
	int size1=1;
	int size2=1;
	queue<int> q[2];
	q[0].push(st);
	q[1].push(ed);
	vis[st]=1;
	vis[ed]=2;
	while((!q[0].empty())&&(!q[1].empty())){
		if(size1<=size2){
			int now=q[0].front();
			q[0].pop();
			int te=begin[now];
			while(te!=-1){
				if(vis[to[te]]==2)
					return true;
				if(vis[to[te]]==0){
					q[0].push(to[te]);
					vis[to[te]]=1;
				}
				te=next[te];
			}
		}
		else{
			int now=q[1].front();
			q[1].pop();
			int te=begin[now];
			while(te!=-1){
				if(vis[to[te]]==1)
