	vector<v> nodes;

	graph(int n) {
		nodes.resize(n);
	}
	void read(int n) {
		while (n--) {
			int s = in(), t = in();
			nodes[s].push_back(t);
			nodes[t].push_back(s);
		}
	}
	bool find(int s, int t, v &f) {
		if (s == t)
			return true;
		f[s] = 1;
		for (int x: nodes[s])
			if (!f[x] && find(x, t, f))
				return true;
		return false;
	}
	bool find(int s, int t) {
		v foot_stamp(nodes.size());
		return find(s, t, foot_stamp);
	}
};

