int init(int n){
	for(int i = 0; i < n; i++){
		ran[i] = 0;
		par[i] = i;
	}
}

int find(int x){
	return par[x] ==  x ? x : par[x] = find(par[x]);
}

void unite(int x, int y){
	x = find(x);
	y = find(y);

	if(x == y)return;

	if(ran[y] > ran[x]){
		par[x] = y;
	} else {
		par[y] = x;
		if(ran[y] == ran[x]) ran[x]++;
	}
}

bool same(int x, int y){
	return find(x) == find(y);
}


