using namespace std;

vector<set<int>> A;

bool dfs(int s, int t) {
    auto& S = A[s];
    if (S.find(t) != S.end()) {
        return true;
    }
    for (auto it = S.begin(); it != S.end(); ++it) {
        if (*it != t) {
            auto i = *it;
            if (dfs(i, t)) {
                return true;
            }
        }
    }
    return false;
}

