        nd[i].height = 1;
        nd[i].parent = -1;
    }

    for(i=0;i<m;i++){
        scanf("%d %d",&s,&t);
        join(s,t);
    }

    scanf("%d",&q);
    for(i=0;i<q;i++){
        scanf("%d %d",&s,&t);
        if(isFriend(s,t))printf("yes\n");
        else printf("no\n");
    }
    return 0;
}

