	bool FVisited;

public:
	TUser();
	void AddFriend(TUser* Friend);
	bool IsAccesible(TUser* Target);
};

TUser::TUser()
:FVisited(false)
{
}

void TUser::AddFriend(TUser* Friend)
{
	if(std::find(FAccessible.begin(), FAccessible.end(), Friend) != FAccessible.end()) return;
	FAccessible.push_back(Friend);
}

bool TUser::IsAccesible(TUser* Target)
{
	if(FVisited) return false;
	FVisited = true;
	if(std::find(FAccessible.begin(), FAccessible.end(), Target) != FAccessible.end()) return true;
	for(unsigned int i = 0; i < FAccessible.size(); ++i){
		if(FAccessible[i]->IsAccesible(Target)) return true;
	}
	return false;
}

