// 友達関係を検索するための関数
// start    : 検索を開始する最初のユーザー
// goal     : 友達関係の最後のユーザー
// user_num : 全ユーザー数
bool search_relation(int start, int goal, int user_num)
{

    // 友達関係がつながるかを確認する
    // 幅優先探索が良いかもしれない - キューを使うことが必要
    // 関係がループになっていることを検知することが必要
    // 距離配列を定義して, ユーザー数の2倍を超えたら探索を打ち切るようにする

    bool ret = false;
    int loop_num = 0, user_id;

    queue<int> Q;

    // 開始点をキューにプッシュする
    Q.push(start);

    while( !Q.empty() )
    {
        // キューの先頭要素を取得
        int u = Q.front();
        Q.pop();

        // 訪問情報の更新
        ary_visit[u] = REACH;

        for(int v = 0; v < ary_Link[u].relation_num; v++)
        {
            // 友達関係にあるユーザーの検索
            user_id = ary_Link[u].v_relation[v];

            if( ary_visit[user_id] == UN_REACH )
            {
                // ----- 未訪問の頂点が見つかった -----

                // キューにプッシュする
                Q.push(user_id);

                if( user_id == goal )
                {
                    // 友達のつながりが確認できたので処理を終了する
                    ret = true;
                    break;
                }

                //if( loop_num > user_num )
                //{
                    // 友達関係でたどりつけなかった
                //    break;
                //}

                //loop_num++;
            }
        }

    }

    return ret;
}

