#include <iostream>
#include <vector>
#include <stack>
using namespace std;
static const int NIL = -1;

void dfs(int r, int n, vector<int> G[], int con_id, int connection[]) {
    stack<int> S;
    S.push(r);
    connection[r] = con_id;

    while (!S.empty()) {
        int u = S.top();
        S.pop();

        for (int i = 0; i < G[u].size(); i++) {
            int v = G[u][i];
            if (connection[v] == NIL) {
                connection[v] = con_id;
                S.push(v);
            }
        }
    }
}

int main() {
    int n, s, t, m, q;
