        G[s].push_back(t);
        G[t].push_back(s);
    }

    int id = 1;
    int connection[n];
    for (int i = 0; i < n; i++) connection[i] = NIL;
    for (int u = 0; u < n; u++) {
        if (connection[u] == NIL) dfs(u, n, G, id++, connection);
    }

    cin >> q;

    for (int i = 0; i < q; i++) {
        cin >> s >> t;
        if (connection[s] == connection[t]) {
            cout << "yes" << endl;
        } else {
            cout << "no" << endl;
        }
    }

    return 0;
}

