#pragma endregion Macro

struct unionfind {  // size:要素数,tree：unionfind木
    int n;
    vector<int> tree_root;
    vector<int> tree_depth;
    unionfind(int temp) {
        n = temp;
        tree_root.assign(n, 0);
        tree_depth.assign(n, 1);
        for (int i = 0; i < n; i++) { tree_root[i] = i; }
    }

    // rootを探す
    int root(int index) {
        vector<int> temp_list(0);
        int temp = tree_root[index];
        while (index != temp) {
            temp_list.emplace_back(index);
            index = temp;
            temp = tree_root[index];
        }
        for (int i : temp_list) { tree_root[i] = index; }
        return index;
    }
    //結合
    void unite(int index1, int index2) {
        int r1 = root(index1);
        int r2 = root(index2);
        if (r1 != r2) {
            int d1 = tree_depth[r1];
            int d2 = tree_depth[r2];
            if (d1 <= d2) {
                tree_root[r1] = r2;
                tree_depth[r2] = max(d1 + 1, d2);
            } else {
                tree_root[r2] = r1;
                tree_depth[r1] = max(d2 + 1, d1);
            }
        }
    }
    //同じか判定
    bool same(int index1, int index2) {
        int r1 = root(index1);
        int r2 = root(index2);
        return r1 == r2;
    }
    //連結成分の個数
    int component() {
        set<int> s;
        for (int i : tree_root) { s.insert(i); }
        return (int)s.size();
    }
};

int main() {
    PRE_COMMAND
    int n, m, q;
    INPUT(n, m);
    unionfind u(n);
    REP(i, m) {
        int a, b;
        INPUT(a, b);
        u.unite(a, b);
    }
    INPUT(q);
    REP(i, q) {
        int a, b;
        INPUT(a, b);
        if (u.same(a, b)) {
            PRINT("yes");
        } else {
            PRINT("no");
        }
    }
}

