class union_find{
public:
	int n;
	vector<int> parent;
	union_find(int _n):n(_n){
		parent.resize(n);
		rep(i, n){
			parent[i]=i;
		}
	}

	int get_parent(int x){
		if(parent[x]==x)return x;
		return parent[x] = get_parent(parent[x]);
	}

	bool is_same(int a, int b){
		int ap = get_parent(a);
		int bp = get_parent(b);
		return ap == bp;
	}

	void merge(int a, int b){
		int ap = get_parent(a);
		int bp = get_parent(b);
		if(ap==bp)return;
		parent[bp] = ap;
	}

};

