void dfs_visit(int u, int id)
{
  if(visited[u] != 0) return;
  visited[u] = id;
  stack<int> s;//  诶~有意思。用stack来实现DFS一次把下层节点全压栈与一次压下层的一个节点仅仅是子节点的访问顺序颠倒了。
  s.push(u);
  while(!s.empty())
  {
    int v = s.top(); s.pop();
    for(int i=0; i<G[v].size(); i++)
    {
      int x = G[v][i];
      if(visited[x] == 0)
      {
        s.push(x);
        visited[x] = id;
      }
    }
  }
}
