bool dfs(int s, int t, vector<vector<int>> sns, bool* visit) {
  if (s == t) {
    return true;
  }
  if (visit[s]) {
    return false;
  }

  visit[s] = true;

  int len = sns[s].size();
  for (int i = 0; i < len; i++) {
    int next = sns[s][i];
    if (dfs(next, t, sns, visit)) {
      return true;
    }
  }
  return false;
}

