    else
        x = find(*x.parent);
    return x;
}

void marge(node x, node y){
    int height_x = x.rank;
    int height_y = y.rank;
    x = find(x);
    y = find(y);
    if(x.id == y.id)
        return;
    if(height_x > height_y)
        y.parent = &x;
    else
        x.parent = &y;
    return;
}

bool judge(node x, node y){
    x = find(x);
    y = find(y);
    return x.id == y.id;
}

int main() {
    cin >> n >> m;
    node person[n];
    REP(i, n){
        person[i].id = i;
        person[i].parent = NULL;
        person[i].rank = 0;
    }
    REP(i, m){
        int s, t;
        cin >> s >> t;
        if(person[t].rank == 0){
            person[t].parent = &person[s];
            person[t].rank = person[s].rank + 1;
        } else if(person[s].rank == 0){
            person[s].parent = &person[t];
            person[s].rank = person[t].rank + 1;
        } else marge(person[s], person[t]);
    }
    int q;
    cin >> q;
    REP(i, q){
        int s, t;
        cin >> s >> t;
        if(judge(person[s], person[t]))
            cout << "yes" << endl;
        else
            cout << "no" << endl;
    }
    return 0;
}

