#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 100000
#define MAX_M 100000

typedef struct EDGE {
    int to;
    struct EDGE *next;
} edge;

int buff_size;
edge buff[MAX_M + MAX_M];
edge *adj[MAX_N];

void init(int n, int m) {
    int i;
    for(i = 0; i < n; ++i) {
        adj[i] = NULL;
    }
    for(i = 0; i < m; ++i) {
        buff[i].next = NULL;
    }
    buff_size = 0;
}

edge *new_edge() {
    return buff + buff_size++;
}

void add_edge(int u, int v) {
    edge *e = new_edge();
    e->to = v;
    e->next = adj[u];
    adj[u] = e;
}

int head, tail;
int queue[MAX_N];

void enqueue(int data) {
    queue[tail++] = data;
}

int dequeue() {
    return queue[head++];
}

int empty() {
    return head == tail;
}

void clear() {
    head = tail = 0;
}

int next_label;
int label[MAX_N];

void bfs(int v) {
    edge *e;

    clear();
    enqueue(v);

    label[v] = next_label;
    while(!empty()) {
        const int v = dequeue();
        for(e = adj[v]; e != NULL; e = e->next) {
            if(label[e->to] == -1) {
                label[e->to] = next_label;
                enqueue(e->to);
            }
        }
    }
    ++next_label;
}

int main() {
    int n, m, q;
    int u, v;
    int s, t;
    int i;

    scanf("%d %d", &n, &m);
    init(n, m);

    for(i = 0; i < m; ++i) {
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    memset(label, -1, sizeof(label));
    for(i = 0; i < n; ++i) {
        if(label[i] == -1) bfs(i);
    }

    scanf("%d", &q);
    while(q--) {
        scanf("%d %d", &s, &t);
        puts(label[s] == label[t] ? "yes" : "no");
    }

    return EXIT_SUCCESS;
}

