// Union Find
typedef struct UnionFind {
    int parent[100000];
    int rank[100000];
    int size[100000];
} UnionFind;

void uf_init(UnionFind *UF) {
    const int N = 100000;
    for(int i = 0; i < N; ++i) {
        UF->parent[i] = i;
        UF->rank[i] = 0;
        UF->size[i] = 1;
    }
}

#define uf_same(UF, x, y) (uf_find((UF), (x)) == uf_find((UF), (y)))

int uf_find(UnionFind *UF, int x) {
    if(x == UF->parent[x]) return x;
    else return UF->parent[x] = uf_find(UF, UF->parent[x]);
}

void uf_unite(UnionFind *UF, int x, int y) {
    x = uf_find(UF, x), y = uf_find(UF, y);
    if(x == y) return;
    if(UF->rank[x] < UF->rank[y]) UF->parent[x] = y;
    else {
        UF->parent[y] = x;
        if(UF->rank[x] == UF->rank[y]) UF->rank[x]++;
        int tmp = x, x = y, y = tmp;
    }
    UF->size[y] += UF->size[x];
    UF->size[x] = 0;
}
//


int main(int argc, char **argv) {
    int n = get_uint();
    int m = get_uint();
    UnionFind UF;
    uf_init(&UF);
    for(int i = 0; i < m; ++i) {
        int s = get_uint();
        int t = get_uint();
        uf_unite(&UF, s, t);
    }
    int q = get_uint();
    for(int i = 0; i < q; ++i) {
        int s = get_uint();
        int t = get_uint();
        puts(uf_same(&UF, s, t) ? "yes" : "no");
    }
    return 0;
}

#include <stdio.h>
#define MAX 100000

int C[MAX] = {0};

void init() {
  int i;
  for (i = 0; i < MAX; ++i) {
    C[i] = i;
  }
}

int Find(int a) {
  if (a == C[a]) {
    return a;
  }

  return C[a] = Find(C[a]);
}

int Same(int a, int b) {
  if (Find(a) == Find(b)) {
    return 1;
  }
  else {
    return 0;
  }
}

void unite(int a, int b) {
  a = Find(a);
  b = Find(b);
  if (a == b) return;
  C[b] = a;
}

int main() {
  int n, m, q, i, j, k;
  init();
  scanf("%d %d", &n, &m);
  for ( i = 0; i < m; ++i ) {
    scanf("%d %d", &j, &k);
    unite(j, k);
  }
  scanf("%d", &q);

  for ( i = 0; i < q; i++ ) {
    scanf("%d %d", &j, &k);
    if (Same(j, k)) {
      printf("yes\n");
    } else {
      printf("no\n");
    }
  }

  return 0;
}

