int uf_find(UnionFind *UF, int x) {
    if(x == UF->parent[x]) return x;
    else return UF->parent[x] = uf_find(UF, UF->parent[x]);
}

void uf_unite(UnionFind *UF, int x, int y) {
    x = uf_find(UF, x), y = uf_find(UF, y);
    if(x == y) return;
    if(UF->rank[x] < UF->rank[y]) UF->parent[x] = y;
    else {
        UF->parent[y] = x;
        if(UF->rank[x] == UF->rank[y]) UF->rank[x]++;
        int tmp = x, x = y, y = tmp;
    }
    UF->size[y] += UF->size[x];
    UF->size[x] = 0;
}
//


int main(int argc, char **argv) {
    int n = get_uint();
    int m = get_uint();
    UnionFind UF;
    uf_init(&UF);
    for(int i = 0; i < m; ++i) {
        int s = get_uint();
        int t = get_uint();
        uf_unite(&UF, s, t);
    }
    int q = get_uint();
    for(int i = 0; i < q; ++i) {
        int s = get_uint();
        int t = get_uint();
        puts(uf_same(&UF, s, t) ? "yes" : "no");
    }
    return 0;
}

