int bfs(int s, int t,int size)
{
        int i, pos, head = 0, tail = 0;
        queue[tail++] = s;
        for (i = 0; i < size; i++) {
                visit[i] = 0;
        }
        visit[s] = 1;
        do {
                pos = queue[head++];
                for (i = 0; i < size; i++) {
                        if (matrix[pos][i] && !visit[i]) {
                                if (i == t) return 1;
                                visit[i] = 1;
                                queue[tail++] = i;
                        }
                }
        } while (head != tail);
        return 0;
}

