     p++;
       } else {
     if (u[s] != -1 && u[t] == -1) {
       u[t] = u[s];
       net[u[s]]++;
     } else if (u[s] == -1 && u[t] != -1) {
       u[s] = u[t];
       net[u[t]]++;
     } else {
       if (u[s] != u[t]) {
         if (net[u[s]] > net[u[t]]) merge(u, net, u[t], u[s]);
         else merge(u, net, u[s], u[t]);
