void visit(int u,int G[n][n]){
  int i;

  color[u] = GRAY;
  d[u] = ++time;
  for(i=1;i<=n;i++){
    if(G[u][i]==1 && color[i]==WHITE) visit(i,G);
  }
  color[u] = BLACK;
  f[u] = ++time;
}


int rooting(int s,int t,int G[n][n]){
  int i;

  for(i=0;i<n;i++){
    color[i]=WHITE;
    d[i] = -1;
    f[i] = -1;
  }
  time = 0;

  visit(s,G);

  if(f[t]!=-1) return 1;
  else 0;
}



