  }
}

void neighbor_list(int from, int to) {
  int count;
  struct Adj *adj, *dummy;
  adj = (struct Adj*)malloc(sizeof(struct Adj));
  adj->key = to;
  if (node[from].k == 0) {
    node[from].adj = adj;
    node[from].k++;
  }
  else {
    dummy = node[from].adj;
    count = node[from].k - 1;
    while (count--) {
      dummy = dummy->adj;
    }
    dummy->adj = adj;
    node[from].k++;
  }
  adj = (struct Adj*)malloc(sizeof(struct Adj));
  adj->key = from;
  if (node[to].k == 0) {
    node[to].adj = adj;
    node[to].k++;
  }
  else {
    dummy = node[to].adj;
    count = node[to].k - 1;
    while (count--) {
      dummy = dummy->adj;
    }
    dummy->adj = adj;
    node[to].k++;
  }
}

