  }
}

void solve(int num, int g) {
  struct Adj *dummy;
  for (int i = 0; i < node[num].k; i++) {
    if (i == 0)
      dummy = node[num].adj;
    else
      dummy = dummy->adj;
    if (node[dummy->key].group == -1) {
      node[dummy->key].group = g;
      solve(dummy->key, g);
    }
  }
}

