  for (i = 0; i < n; i++) {
    affiliation[i] = -1;
  }
  group = (long*)malloc(sizeof(long) * m);
  for (i = 0; i < m; i++) {
    group[i] = 0;
  }
  p = 0;
  for (i = 0; i < m; i++) {
    scanf("%ld %ld", &s, &t);
    if(s != t) {
      if(affiliation[s] == -1 && affiliation[t] == -1) {
	affiliation[s] = p;
	affiliation[t] = p;
	group[p] += 2;
	p++;
      }
      else if(affiliation[s] != -1 && affiliation[t] == -1) {
	affiliation[t] = affiliation[s];
	group[affiliation[s]]++;
      }
      else if(affiliation[s] == -1 && affiliation[t] != -1) {
	affiliation[s] = affiliation[t];
	group[affiliation[t]]++;
      }
      else if(affiliation[s] != affiliation[t]){
	unite(affiliation,group,s,t);
      }
    }
  }
  scanf("%ld",&q);
