#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define BUF_SIZE 20

struct uni {
  struct uni *parent;
  int depth;
};

struct uni *find_root(struct uni *u) {
  while(u->parent != u) {
    u = u->parent;
  }
  return u;
}

int check_group(struct uni *u1, struct uni *u2) {
  struct uni *root1 = find_root(u1);
  struct uni *root2 = find_root(u2);
  return root1 == root2;
}

void unite(struct uni *u1, struct uni *u2) {
  if(check_group(u1, u2)) return;
  struct uni *root1 = find_root(u1);
  struct uni *root2 = find_root(u2);
  if(root1->depth > root2->depth) {
    root2->parent = root1;
  } else {
    root1->parent = root2;
    if(root1->depth == root2->depth) {
      root2->depth++;
    }
  }
}

int main(void) {
  FILE *fp = stdin;
  char line[BUF_SIZE];
  if(!fgets(line, BUF_SIZE, fp)) return 0;

  int num, conns;
  sscanf(line, "%d %d", &num, &conns);

  int i, j;
  struct uni *graphs = malloc(sizeof(struct uni)*num);
  for(i = 0; i < num; i++) {
    graphs[i].parent = &graphs[i];
    graphs[i].depth = 0;
  }

  for(i = 0; i < conns; i++) {
    if(!fgets(line, BUF_SIZE, fp)) return 0;
    int s1, s2;
    sscanf(line, "%d %d", &s1, &s2);
    unite(&graphs[s1], &graphs[s2]);
  }


  if(!fgets(line, BUF_SIZE, fp)) return 0;
  int queries;
  sscanf(line, "%d", &queries);

  for(i = 0; i < queries; i++) {
    int s1, s2;
    if(!fgets(line, BUF_SIZE, fp)) return 0;
    sscanf(line, "%d %d", &s1, &s2);
    int flag = check_group(&graphs[s1], &graphs[s2]);
    printf("%s\n", flag ? "yes" : "no");
  }
  return 0;
}

