void add(Node *node,int t){
    Node* nn;
    if(node->next==NULL){
    	nn = (Node*)malloc(sizeof(Node));
        nn->num=t;nn->next=NULL;
        node->next=nn;
    }else{
        add(node->next,t);
    }
}

void tansa(Node node[],int num,int color,int ban[]){
    ban[num]=color;
    for(Node *no=node[num].next;no!=NULL;no=no->next){
        if(ban[no->num]==-1){
            tansa(node,no->num,color,ban);
        }
    }
}

