#define MAX 100010

struct NODE {
	int num;
	struct NODE* next;
	struct NODE* prev;
};

struct NODE SNS[MAX];

int d[MAX] = { 0 };

void Add(int Lperson, int Rperson) {
	struct NODE* addition = (struct NODE*)malloc(sizeof(struct NODE));
	struct NODE* prim = SNS[Lperson].next;
	SNS[Lperson].next = addition;
	addition->prev = &SNS[Lperson];
	addition->next = prim;
	if (prim != NULL) prim->prev = addition;
	addition->num = Rperson;
}

void FandC(int L, int cnt) {
	struct NODE* run = &SNS[L];
	while (run != NULL) {
		if (d[run->num] != cnt) {
			d[run->num] = cnt;
			if (run->prev != NULL)FandC(run->num, cnt);
		}
		run = run->next;
	}
}

int main() {
	int n, m, q;
	int Lperson, Rperson;
	for (int i = 0; i < MAX; i++) {
		SNS[i].num = i;
		SNS[i].next = NULL;
		SNS[i].prev = NULL;
	}
	scanf("%d %d", &n, &m);
	for (int i = 0; i < m; i++) {
		scanf("%d %d", &Lperson, &Rperson);
		Add(Lperson, Rperson);
		Add(Rperson, Lperson);
	}
	for (int i = 0; i < n; i++) {
		if (d[i] == 0)FandC(i, i + 1);
	}
	scanf("%d", &q);
	for (int i = 1; i <= q; i++) {
		scanf("%d %d", &Lperson, &Rperson);
		if (d[Lperson] == d[Rperson])printf("yes\n");
		else printf("no\n");
	}

	return 0;
}

#include <stdio.h>
#define max 100000

int n,m,q,from,to;
int rank[max],parent[max];

int find(int x)
{
	if(x == parent[x])
	{
		return x;
	}
	else{
		return parent[x] = find(parent[x]);
	}
}

void unite(int x,int y)
{
	x = find(x);
	y = find(y);

	if(x == y)
	{
		return;
	}
	if(rank[x] < rank[y])
	{
		parent[x] = y;
	}
	else{
		parent[y] = x;
		if(rank[x] == rank[y])
		{
			rank[x]++;
		}
	}
}

int main(void)
{
	int i;
	scanf("%d %d",&n,&m);

	for(i = 0; i < n; i++)
	{
		rank[i] = 0;
		parent[i] = i;
	}
	for(i = 0; i < m; i++)
	{
		scanf("%d %d",&from,&to);
		if(find(from) == find(to))
		{
			continue;
		}
		unite(from,to);
	}
	scanf("%d",&q);
	int left , right;

	for(i = 0; i < q; i++)
	{
		scanf("%d %d",&left,&right);
		if(find(left) == find(right))
		{
			printf("yes\n");
		}
		else
		{
			printf("no\n");
		}
	}
	return 0;
}

