int push(int stack[],int x,int top){
	stack[top++]=x;
	return top;
}

int pop(int stack[],int *top){
	(*top)--;
	return stack[*top];
}

void Get_Color(int C[],int x,list *L[]){
	int stack[MAX];
	int top=0;
	int temp;
	list *p;

