		while(getchar() != '\n');

		V[id1].N[V[id1].len_N] = id2;
		V[id1].len_N++;

		V[id2].N[V[id2].len_N] = id1;
		V[id2].len_N++;
	}

	scanf("%d", &q);
	for(i = 0; i < q; i++)
	{
		scanf("%d %d", &id1, &id2);
		while(getchar() != '\n');

		if(CanReach(id1, id2))
		printf("yes\n");

		else
		printf("no\n");
	}

	return 0;
}

void setDefault()
{
	int i;

	for(i = 0; i < n; i++)
	{
		V[i].len_N = 0;
	}
}

int CanReach(int start, int goal)
{
	int i;
	int flag[MAX_N];

	for(i = 0; i < n; i++)
	{
		flag[i] = 0;
	}

	reTravel(start, flag);

	if(flag[goal] == VISITED)
	return 1;

	return 0;
}

void reTravel(int t, int flag[])
{
	int i;
	int next;

	flag[t] = VISITED;

	for(i = 0; i < V[t].len_N; i++)
	{
		next = V[t].N[i];

		if(flag[next] != VISITED)
		reTravel(next, flag);
	}
}

