typedef struct _node {
  unsigned int id;
  unsigned int rank;
  struct _node* parent;
} Node;

typedef Node* NodePointer;

NodePointer root(NodePointer, unsigned int);
void unite(NodePointer, unsigned int, unsigned int);
bool isSame(NodePointer, unsigned int, unsigned int);

int main () {
  unsigned int n, m, q;
  unsigned int s, t;

  scanf("%u %u", &n, &m);
  NodePointer friends = (NodePointer)malloc(sizeof(Node)*n);
  for (unsigned int i = 0; i < n; ++i) {
    friends[i].id     = i;
    friends[i].rank   = 0;
    friends[i].parent = &friends[i];
  }

  for (unsigned int i = 0; i < m; ++i) {
    scanf("%u %u", &s, &t);
    unite(friends, s, t);
  }

  scanf("%u", &q);
  for (unsigned int i = 0; i < q; ++i) {
    scanf("%u %u", &s, &t);    
    if (isSame(friends, s, t)) {
      printf("yes\n");
    } else {
      printf("no\n");
    }   
  }

  return 0;
}

NodePointer root(NodePointer friends, unsigned int x) {
  if (friends[x].parent == &friends[x]) {
    return &friends[x];
  } else {
    friends[x].parent = root(friends, friends[x].parent->id);
    return friends[x].parent;
  }
}

void unite (NodePointer friends, unsigned int x, unsigned int y) {
  NodePointer rx = root(friends, x);
  NodePointer ry = root(friends, y);
  if (rx == ry) {
    return;
  }

  if (rx->rank < ry->rank) {
    rx->parent = ry;
  } else {
    ry->parent = rx;
    if (rx->rank == ry->rank) {
      rx->rank++;
    }
  }
}

bool isSame (NodePointer friends, unsigned int x, unsigned int y) {
  NodePointer rx = root(friends, x);
  NodePointer ry = root(friends, y);

  return rx == ry;
}

