void merge(int *u, int *net, int oldnet, int newnet){
  int i; 
  for (i = 0; i < n; i++) {
    if (u[i] == oldnet){
      u[i] = newnet;
    }
  } 
  net[newnet] += net[oldnet];
  net[oldnet] = 0;
}

