void
cleanup(int ecode)
{
	exit(ecode);
}

int
que_empty()
{
	return que_in == que_out;
}

void
que_push(int x)
{
	queue[que_in] = x;
	que_in = (que_in + 1) % QUE_SIZE;
	if (que_in == que_out)
	{
		fprintf(stderr, "Queue overflow. size:%d\n", QUE_SIZE);
		cleanup(1);
	}
}

void
que_pop()
{
	if (que_out == que_in)
	{
		fprintf(stderr, "Queue underflow\n");
		cleanup(1);
	}

	que_out = (que_out + 1) % QUE_SIZE;
}

int
que_front()
{
	return queue[que_out];
}

void
bfs(int u, int c)
{
	int v;
	int r;
	int l;

	color[u] = c;
	que_push(u);
	while (!que_empty())
	{
		r = que_front(); que_pop();
		for (l = g[r]; l != nil; l = es[l].next)
		{
			v = es[l].to;
			if (color[v] == nil)
			{
				color[v] = c;
				que_push(v);
			}
		}
	}
}

