        else Q[t] = G[i][0];
        Z[i] = 1;
      }
    }
  }

  h = 0; r = 0;flag = 1;
  while(flag == 1){
    flag = 0;
    k = Q[t];
    t++;
    for( i = 0; i < m; i++ ){
      for( j = 0; j <= 1; j++ ){
        if( k == G[i][j] && Z[i] != 1 ){
         Z[i] = 1;
          if ( j == 0 ) {
            Q[h] = G[i][1];
            h++;
            flag = 1;
            if( G[i][1] == b ) {
              r = 1;
              break;
            }
          } else {
            Q[h] = G[i][0];
            h++;
            flag = 1;
            if( G[i][0] == b ) {
              r = 1;
              break;
            }
          }
        }
      }
    }
  }

  if ( r == 1 ){
