typedef struct node {
  int x;
  struct node* prev;
  struct node* next;
} list;

typedef struct {
  list* head;
  list* tail;
} Graph;
Graph graph[100001];

list* newnode(int x) {
  list* res = (list*)malloc(sizeof(list));
  res->x = x;
  res->prev = NULL;
  res->next = NULL;
  return res;
}
void deletenode(list* p) {
  p->prev->next = p->next;
  p->next->prev = p->prev;
  free(p);
}
void init_graph(Graph* g) {
  g->head = newnode(-1);
  g->tail = newnode(-1);
  g->head->next = g->tail;
  g->tail->prev = g->head;
}
void insert(Graph* g, int x) {
  list* p = newnode(x);
  p->next = g->head->next;
  p->prev = g->head;
  g->head->next->prev = p;
  g->head->next = p;
}
void clear_graph(Graph* g) {
  while(g->head->next != g->tail) {
    deletenode(g->head->next);
  }
  free(g->head);
  free(g->tail);
}

#define Q_LEN 1000000
int queue[Q_LEN];
int qhead, qtail;
void enque(int i) {
  if((qtail+1)%Q_LEN == qhead) return;
  queue[qtail] = i;
  qtail++;
  qtail %= Q_LEN;
}
int deque() {
  int res;
  if(qhead == qtail) return -1;
  res = queue[qhead];
  qhead++;
  qhead %= Q_LEN;
  return res;
}
int empty() {
  return qhead == qtail;
}
void clear_queue() {
  while(!empty()) deque();
}

