			}
		}
	}
	return 0;
}

void freeList(nodeList *header[],int n){
	nodeList *p,*next;
	int i;
	for(i=0;i<n;i++){
		p=header[i];
		next=p->next;
		while(next!=NULL){
			free(p);
			p=next;
			next=p->next;
		}
	}
}




