    if(s != t) {
      if(affiliation[s] == -1 && affiliation[t] == -1) {
	affiliation[s] = p;
	affiliation[t] = p;
	group[p] += 2;
	p++;
      }
      else if(affiliation[s] != -1 && affiliation[t] == -1) {
	affiliation[t] = affiliation[s];
	group[affiliation[s]]++;
      }
      else if(affiliation[s] == -1 && affiliation[t] != -1) {
	affiliation[s] = affiliation[t];
