void enqueue(int x){ /* キューの末尾に要素 x を追加 */
  Q[tail] = x;
  if (tail + 1 == n) tail = 0;
  else tail++;
}

int dequeue(void){ /* キューの先頭から要素を取り出す */
  int x;
  x = Q[head];
  if (head + 1 == n) head = 0;
  else head++;
  return x;
}

