#define LARGE 10000
#define INF 100000000
#define MIN(a,b) ((a) < (b) ? (a):(b))

int V,E;
int color=0;
int C[LARGE];

typedef struct list{
	int id;
	struct list *next;
}list;


list * makelist(int x){
	list *new=malloc(sizeof(list));
	new->id=x;
	new->next=NULL;
	return new;
}

void list_insert(list* L[],int x,list *new){
	list **p=&L[x];

	while((*p)!=NULL){
		p=&((*p)->next);
	}
	(*p)=new;

	return;
}

int push(int stack[],int x,int top){
	stack[top++]=x;
	return top;
}

int pop(int stack[],int *top){
	(*top)--;
	return stack[*top];
}

int dfs(int C[],int x,int y,list* L[]){
	int stack[LARGE];
	int top=0;
	int temp;
	list *p;

	color++;
	top=push(stack,x,top);
	while(top>0){
		temp=pop(stack,&top);
		if(C[temp]==0)C[temp]=color;
		p=L[temp];
		while(p!=NULL){
			if(C[p->id]==0){
				if(p->id==y)return 1;
				top=push(stack,p->id,top);
				C[p->id]=color;
			}
			p=p->next;
		}
	}

	return 0;
}

