		new=makelist(s);
		list_insert(L,t,new);
	}

	scanf("%d",&q);
	for(i=0;i<q;i++){
		for(i=0;i<V;i++)C[i]=0;
		scanf("%d %d",&x,&y);
		if(dfs(C,x,y,L))printf("yes\n");
		else printf("no\n");
	}


	return 0;

}

