edge *adj[MAX_N];

void init(int n, int m) {
	int i;
	for(i = 0; i < n; ++i) {
		adj[i] = NULL;
	}
	for(i = 0; i < m; ++i) {
		buff[i].next = NULL;
	}
	buff_size = 0;
}

edge *new_edge() {
	return buff + buff_size++;
}

void add_edge(int u, int v) {
	edge *e = new_edge();
	e->to = v;
	e->next = adj[u];
	adj[u] = e;
}

int next_label;
int label[MAX_N];

void dfs(int v) {
	edge *e;
	label[v] = next_label;
	for(e = adj[v]; e != NULL; e = e->next) {
		if(label[e->to] == -1) dfs(e->to);
	}
}

int main() {
	int n, m, q;
	int u, v;
	int s, t;
	int i;

	scanf("%d %d", &n, &m);
	init(n, m);

	for(i = 0; i < m; ++i) {
		scanf("%d %d", &u, &v);
		add_edge(u, v);
		add_edge(v, u);
	}

	memset(label, -1, sizeof(label));
	for(i = 0; i < n; ++i) {
		if(label[i] == -1) {
