    bool->a7 = in;
    break;
  default:
    break;
  }
}

char check_boolean(boolean *bool, int ad) {
  switch (ad) {
  case 0:
    return bool->a0;
    break;
  case 1:
    return bool->a1;
    break;
  case 2:
    return bool->a2;
