boolean **build_matrix(long n) {
  boolean **a = (boolean**)malloc(sizeof(boolean*) * n);
  long i;
  for (i = 0; i < n; i++) {
    a[i] = (boolean*)calloc(n/8,sizeof(boolean));
  }
  return a;
}


void search(boolean **a, long n, boolean **group, long g_num, long u, long *affiliation) {
  if(check_boolean(group[g_num]+u/8,u%8) != 0) return;
  set_boolean(group[g_num]+u/8,u%8,1);
  affiliation[u] = g_num;
  long i;
  for (i = 0; i < n; i++) {
    if(check_boolean(a[u]+i/8,i%8) == 1) {
      search(a,n,group,g_num,i,affiliation);
    }
  }
}

int main()
{
