  group = (boolean**)malloc(sizeof(boolean*) * n);
  long *affiliation;
  affiliation = (long*)malloc(sizeof(long) * n);
  for (i = 0; i < n; i++) {
    affiliation[i] = -1;
  }

  j = 0;
  for (i = 0; i < n; i++) {
    if(affiliation[i] == -1) {
      group[j] = (boolean*)calloc(n/8,sizeof(boolean));
      search(a,n,group,j,i,affiliation);
      j++;
    }
  }

  long q,s,t;
  scanf("%ld",&q);
  for (i = 0; i < q; i++) {
    scanf("%ld %ld",&s,&t);
    if(check_boolean(group[affiliation[s]]+t/8,t%8) == 1) printf("yes\n");
    else printf("no\n");

  }



  for (i = 0; i < n; i++) {
    free(a[i]);
  }
  for (i = 0; i < j; i++) {
    free(group[i]);
  }

  free(a);
  free(group);
  free(affiliation);
  return 0;
}

