	stack[top++]=x;
	return top;
}

int pop(int stack[],int *top){
	(*top)--;
	return stack[*top];
}

void Get_Color(int C[],int x){
	int stack[MAX];
	int top=0;
	int temp;
	int i;

	color++;
	top=push(stack,x,top);
	while(top>0){
		temp=pop(stack,&top);
		if(C[temp]==0)C[temp]=color;
		i=0;
		while(matrix[temp][i]!=-1){
			if(C[matrix[temp][i]]==0){
				top=push(stack,matrix[temp][i],top);
				C[matrix[temp][i]]=color;
			}
			i++;
		}
	}

	return;
}


