#include <stdio.h>
#define MAX 1000
#define WHITE 0
#define GRAY 1
#define BLACK 2
int color[MAX];
int memo[MAX];
int v[MAX][MAX];

int dfs(int u, int t) {
   int stack[MAX];
   int i = 0;
   int j;
   int judge = 0;
   stack[0] = u;
   color[u] = GRAY;
   while (stack[0] != -1) {
	  u = stack[i];
	  judge = 0;
	  if (memo[u] != 0) {
		 for (j = 0; j < memo[u]; ++j) {
			if (color[v[u][j]] == WHITE) {
			   color[v[u][j]] = GRAY;
			   stack[++i] = v[u][j];
			   if (v[u][j] == t)
				  return 1;
			   judge = 1;
			}
		 }
	  }
	  if (judge == 0) {
		 stack[i] = -1;
		 color[u] = BLACK;
		 --i;
	  }
   }
   return 0;
}

int CC(int v[MAX][MAX], int s, int t, int n) {
   int i;
   for (i = 0; i < n; ++i) {
	  color[i] = WHITE;
   }
   return dfs(s, t);
}

int main() {
   int ans[MAX];
   int n, m, q, s, t;
   int vs, vt;
   int i;

   scanf("%d %d", &n, &m);
   for (i = 0; i < n; ++i) {
	  memo[i] = 0;
	  v[i][0] = -1;
   }

   for (i = 0; i < m; ++i) {
	  scanf("%d %d", &vs, &vt);
	  v[vs][memo[vs]] = vt;
	  v[vt][memo[vt]] = vs;
	  ++memo[vs];
	  ++memo[vt];
   }

   scanf("%d", &q);
   for (i = 0; i < q; ++i) {
	  scanf("%d %d", &s, &t);
	  ans[i] = CC(v, s, t, n);
   }

   for (i = 0; i < q; ++i) {
	  if (ans[i] == 1)
		 printf("yes\n");
	  else
		 printf("no\n");
   }
   return 0;
}

