#include <stdio.h>
#include <stdlib.h>

void unite(long *affiliation, long *group, long s, long t) {
  long i,j;
  long p = affiliation[s];
  long q = affiliation[t];
  j = 0;
  for (i = 0; j < group[q]; i++) {
    if(affiliation[i] == q) {
      affiliation[i] = p;
      j++;
    }
  }
  group[p] += group[q];
}

int main()
{
  long n,m,i,s,t,p,q;
  long *affiliation,*group;
  scanf("%ld %ld",&n,&m);
  affiliation = (long*)malloc(sizeof(long) * n);
  for (i = 0; i < n; i++) {
    affiliation[i] = -1;
  }
  group = (long*)malloc(sizeof(long) * m);
  for (i = 0; i < m; i++) {
    group[i] = 0;
  }
  p = 0;
  for (i = 0; i < m; i++) {
    scanf("%ld %ld", &s, &t);
    if(affiliation[s] == -1 && affiliation[t] == -1) {
      affiliation[s] = p;
      affiliation[t] = p;
      group[p] += 2;
      p++;
    }
    else if(affiliation[s] != -1 && affiliation[t] == -1) {
      affiliation[t] = affiliation[s];
      group[affiliation[s]]++;
    }
    else if(affiliation[s] == -1 && affiliation[t] != -1) {
      affiliation[s] = affiliation[t];
      group[affiliation[t]]++;
    }
    else if(affiliation[s] != affiliation[t]){
      unite(affiliation,group,s,t);
    }
  }
  scanf("%ld",&q);
  for (i = 0; i < q; i++) {
    scanf("%ld %ld", &s, &t);
    if(affiliation[s] == affiliation[t]) printf("yes\n");
    else printf("no\n");
  }
  free(affiliation);
  free(group);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct user {
  int network;
};

struct network {
  int members;
};

int n, m;

void merge(struct user *u, struct network *net, int oldnet, int newnet);

int main(int argc, char *argv[])
{
  int i, s, t, p, q;
  struct user *u;
  struct network *net;

  scanf("%d", &n);
  scanf("%d", &m);
  u = (struct user *)malloc(sizeof(struct user) * n);
  net = (struct network *)malloc(sizeof(struct network) * m);
  for (i = 0; i < n; i++) u[i].network = -1;
  for (i = 0; i < m; i++) net[i].members = 0;

  p = 1;

  for (i = 0; i < m; i++) {
    scanf("%d", &s);
    scanf("%d", &t);
    if (u[s].network == -1 && u[t].network == -1) {
      u[s].network = p;
      u[t].network = p;
      net[p].members += 2;
      p++;
    } else {
      if (u[s].network != -1 && u[t].network == -1) {
	u[t].network = u[s].network;
	net[u[t].network].members++;
      } else if (u[s].network == -1 && u[t].network != -1) {
	u[s].network = u[t].network;
	net[u[s].network].members++;
      } else {
	if (net[u[s].network].members > net[u[t].network].members) {
	  merge(u, net, u[t].network, u[s].network);
	} else {
	  merge(u, net, u[s].network, u[t].network);
	}
      }
    }
  }

  scanf("%d", &q);

  for (i = 0; i < q; i++) {
    scanf("%d", &s);
    scanf("%d", &t);

    if (u[s].network == u[t].network) printf("yes\n");
    else printf("no\n");
  }

  return 0;
}

void merge(struct user *u, struct network *net, int oldnet, int newnet)
{
  int i;

  for (i = 0; i < n; i++) {
    if (u[i].network == oldnet) u[i].network = newnet;
  }

  net[newnet].members += net[oldnet].members;
  net[oldnet].members = 0;
}

