int color[10002],n,vv[1002][1002],k[10002],Q[10002];
int head, tail;

int main()
{
  int i,m,q,s,t;

  /* n ユーザ数 */
  /* m 友達関係の数 */

  scanf("%d %d",&n,&m);

  head = 0;
  tail = 0;
  for(i=0;i<n;i++){
    k[i]=0;
  }

  //友達関係をinput
  for(i=0;i<m;i++){
    scanf("%d%d",&s,&t);
    vv[t][k[t]]=s;
    vv[s][k[s]]=t;
    k[s]++;
    k[t]++;
  }

  //質問をinput
  scanf("%d",&q);
  for(i=0;i<q;i++){
    scanf("%d%d",&s,&t);

    bfs(s);

    if(color[t]==WHITE) printf("no\n");
    else printf("yes\n");
  }

  return 0;
}

void bfs(int s){
  int i,u,v;

  for (u=0;u<n;u++){
    color[u] = WHITE;
  }
  color[s] = GRAY;
  enqueue(s);

  while(head!=tail){
    u = dequeue();
    for(i=0;i<k[u];i++){
      v=vv[u][i];

      if (color[v] == WHITE){

	color[v] = GRAY;
	enqueue(v);
      }
      color[u] = BLACK;
    }
  }
}

void enqueue(int x){ /* キューの末尾に要素 x を追加 */
  Q[tail] = x;
  if (tail + 1 == n) tail = 0;
  else tail++;
}

int dequeue(void){ /* キューの先頭から要素を取り出す */
  int x;
  x = Q[head];
  if (head + 1 == n) head = 0;
  else head++;
  return x;
}

#include <stdio.h>
