#define TRUE 1
#define FALSE 0

typedef struct nl{
	int node;
	struct nl *next;
}nodeList;

nodeList *header[100000];
int isVisited[100000]={0};
void initList(nodeList *header[],int nodeNum){
	int i;
	for(i=0;i<nodeNum;i++){
		header[i]=NULL;
	}
}

void clearArray(int list[],int n){
	int i;
	for(i=0;i<n;i++){
		list[i]=0;
	}
}

void addList(int src,int dest){
	nodeList *p;
	nodeList *data;
	data=(nodeList*)malloc(sizeof(nodeList));
	data->node=dest;
	data->next=0;
	if(header[src]!=NULL){
		for(p=header[src];p->next!=NULL;p=p->next);
		p->next=data;
	}else{
		header[src]=data;
	}
}

int dfs(int src,int dest,int nodeNum){
	if(src==dest)return 1;
	isVisited[src]=1;
	nodeList *p;
	for(p=header[src];p!=NULL;p=p->next){
		if(isVisited[p->node]==0){
			if(dfs(p->node,dest,nodeNum)==1){
				return 1;
			}
		}
	}
	return 0;
}

void freeList(nodeList *header[],int n){
	nodeList *p,*next;
	int i;
	for(i=0;i<n;i++){
		p=header[i];
		next=p->next;
		while(p!=NULL){
			free(p);
			p=next;
			next=p->next;
		}
	}
}




int main(void){
	int n,m;
	int i,j;
	int a,b;
	scanf("%d %d",&n,&m);
	initList(header,n);
	for(i=0;i<m;i++){
		scanf("%d %d",&a,&b);
		addList(a,b);
		addList(b,a);
	}
	int q;
	scanf("%d",&q);
	for(i=0;i<q;i++){
		scanf("%d %d",&a,&b);
		clearArray(isVisited,n);
		if(dfs(a,b,n)==1){
			printf("yes\n");
		}else{
			printf("no\n");
		}
	}
	freeList(header,n);
	return 0;
}

