typedef struct Graph
{
  int numOfAdj;
  int *adj;
  int status;//0:not discovered, 1:discovered, 2:finished
} graph;
int n;//num of vertice
graph *p;//array of vertice
int *d;//array of degree
int *queue;
int head=0,tail=0;
void setAdj(int,int);
int breadthFirstSearch(int,int);
void enqueue(int);
int dequeue(void);
int main(void)
{
  int i,j;//counter
  int num;//num of relations / questions
  int start,end;
  int key,numOfAdj,adj;
  scanf("%d",&n);
  p=(graph*)malloc(sizeof(graph)*n);
  d=(int*)malloc(sizeof(int)*n);
  queue=(int*)malloc(sizeof(int)*n);
  for(i=0;i<n;i++) p[i].numOfAdj=0;
  scanf("%d",&num);
  for(i=0;i<num;i++)
    {
      scanf("%d%d",&start,&end);
      setAdj(start,end);
    }
  scanf("%d",&num);
  for(i=0;i<num;i++)
    {
      scanf("%d%d",&start,&end);
      if(breadthFirstSearch(start,end)!=-1) printf("yes\n");
      else printf("no\n");
    }
  return 0;
}
void setAdj(int start,int end)
{
  int i;//counter
  int *temp=p[start].adj;
  p[start].numOfAdj++;
  p[start].adj=(int*)malloc(sizeof(int)*p[start].numOfAdj);
  for(i=0;i<p[start].numOfAdj-1;i++) p[start].adj[i]=temp[i];
  p[start].adj[i]=end;
}
int breadthFirstSearch(int start,int end)
{
  int i;//counter
  int u,v;
  for(i=0;i<n;i++)
    {
      p[i].status=0;
      d[i]=-1;
    }
  d[start]=0;
  enqueue(start);
  while(head!=tail)
    {
      u=dequeue();
      for(i=0;i<p[u].numOfAdj;i++)
        {
          v=p[u].adj[i];
          if(p[v].status==0)
            {
              p[v].status=1;
              d[v]=d[u]+1;
              enqueue(v);
            }
        }
      p[u].status=2;
    }
  return d[end];
}
void enqueue(int key)
{
  queue[tail]=key;
  tail++;
}
int dequeue(void)
{
  head++;
  return queue[head-1];
}

