#define MAX 100000
#define WHITE 0
#define GRAY 1
#define BLACK 2
int color[MAX];
int memo[MAX];
int v[MAX][MAX];

int dfs(int u, int t) {
   int stack[MAX];
   int i = 0;
   int j;
   int judge = 0;
   stack[0] = u;
   color[u] = GRAY;
   while (stack[0] != -1) {
	  u = stack[i];
	  judge = 0;
	  if (memo[u] != 0) {
		 for (j = 0; j < memo[u]; ++j) {
			if (color[v[u][j]] == WHITE) {
			   color[v[u][j]] = GRAY;
			   stack[++i] = v[u][j];
			   if (v[u][j] == t)
				  return 1;
			   judge = 1;
			}
		 }
	  }
	  if (judge == 0) {
		 stack[i] = -1;
		 color[u] = BLACK;
		 --i;
	  }
   }
   return 0;
}

int CC(int v[MAX][MAX], int s, int t, int n) {
   int i;
   for (i = 0; i < n; ++i) {
	  color[i] = WHITE;
   }
   return dfs(s, t);
}

