#define MAX 100000

int n , m , q , from , to;
int rank[MAX] , parent[MAX];

int find(int x){

	if(x == parent[x]){
		return x;
	}else{
		return parent[x] = find(parent[x]);
	}
}

void unite(int x,int y){

	x = find(x);
	y = find(y);

	if(x == y){
		return;
	}

	if(rank[x] < rank[y]){
		parent[x] = y;
	}else{
		parent[y] = x;
		if(rank[x] == rank[y]){
			rank[x]++;
		}
	}
}

