int pop(int stack[],int *top){
	(*top)--;
	return stack[*top];
}

void Get_Color(int C[],int x){
	int *stack=malloc(sizeof(int)*n);
	int top=0;
	int temp;
	int i;

	color++;
	top=push(stack,x,top);
	while(top>0){
