GG MNode(int key,GG Node)
{
  GG n;
  n=(GG)malloc(sizeof(struct node));
  n->key=key;
  n->next=Node;
  return n;
}
void Insert(int s,int t)
{
  GG GGG;
  GGG=MNode(t,G[s]->next);
  G[s]->next=GGG;
}

void Dye(int c,int id)
{
  int S[100],head=0,u,v;
  GG GGG;
  S[head]=c;
  head++;
  color[c]=id;
  while(head!=0){
    u=S[head-1];
    head--;
    for(GGG=G[u]->next;GGG!=NULL;GGG=GGG->next){
      v=GGG->key;
      if(color[v]==0){
        color[v]=id;
	S[head]=v;
	head++;
      }
    }
  }
}

#include<stdio.h>

#define N 100000

int ID[N]={0};

void def(){
	int i;
	for(i=0;i<N;++i){
		ID[i]=i;
	}
}
int find(int a){
	if(a==ID[a]){
		return a;
	}
	return ID[a]=find(ID[a]);
}

int Judge(int a, int b){
	if(find(a)==find(b))return 1;
	else return 0;
}

void unite(int a, int b){
	a=find(a);
	b=find(b);

	if(a==b)return;
	ID[b]=a;
}

int main(){
	int n,m,q,i,s,t;
	def();
	scanf("%d %d\n", &n, &m);
	for(i=0; i<m; i++){
		scanf("%d %d\n", &s, &t);
		unite(s,t);}
	scanf("%d\n",&q);

	for(i=0; i<q; i++){
		scanf("%d %d\n", &s, &t);
		if (Judge(s,t) == 1)printf("yes\n");
		else printf("no\n");
	}
	return 0;
}

