}

#include <stdio.h>
#include <stdlib.h>

#define NIL -1
#define REALLOC_SIZE 10

typedef struct _node {
	int touched;
	int childNum;
	int *childHead;
} node;

typedef struct _queue {
	int head;
	int tail;
	int *ary;
} queue;

void enqueue(queue *q, int value) {
	q->ary[q->tail++] = value;
}

int dequeue(queue *q) {
	return q->ary[q->head++];
}

node *allocNode() {
	node *p = (node *)malloc(sizeof(node));
	p->touched = NIL;
	p->childNum = 0;
	p->childHead = (int *)malloc(sizeof(int) * REALLOC_SIZE);
	return p;
}

void terminate(queue* queue, node **top, int n) {
	int i;
	for (i = 0; i < n; i++)	free(top[i]->childHead);
	free(top);
	free(queue->ary);
}

int dfs(node **top,int n, queue *q, int q1, int q2) {
	int i, u, v, cn;
	q->head = q->tail = 0;
	for (i = 0; i < n; i++) top[i]->touched = 0;
	top[q1]->touched = 1;
	enqueue(q, q1);
	while (q->head != q->tail) {
		u = dequeue(q);
		cn = top[u]->childNum;
		for (i = 0; i < cn; i++) {
			v = top[u]->childHead[i];
			if (v == q2) return 1;
			if (top[v]->touched == 0) {
				top[v]->touched = 1;
				enqueue(q, v);
			}
		}
	}
	return 0;
}

int main() {
	int i, n, m, s, t, q, q1, q2;
	node **top;
	queue queue;
	int *tmp;
	int size;


	scanf("%d %d", &n, &m);
	top = (node **)malloc(sizeof(node *) * n);
	for (i = 0; i < n; i++) top[i] = allocNode();
	queue.ary = (int *)malloc(sizeof(int) * n);

	for (i = 0; i < m; i++) {
		scanf("%d %d", &s, &t);
		top[s]->childHead[top[s]->childNum++] = t;
		if (top[s]->childNum % REALLOC_SIZE == 0) {
			size = top[s]->childNum / REALLOC_SIZE;
			tmp = (int *)realloc(top[s]->childHead,sizeof(int) * REALLOC_SIZE * size);
			if (tmp == NULL) {
				terminate(&queue, top, n);
				exit(1);
			}
			top[s]->childHead = tmp;
		}
	}

	scanf("%d", &q);
	for (i = 0; i < q; i++) {
		scanf("%d %d", &q1, &q2);
		if (dfs(top,n,&queue,q1,q2)) printf("yes\n");
		else printf("no\n");
	}

	terminate(&queue, top, n);
	return 0;
}

