int bfs(int s, int t,int size)
{
        int i, pos, head = 0, tail = 0;
        struct node *n;
        queue[tail++] = s;
        for (i = 0; i < size; i++) {
                visit[i] = 0;
        }
        visit[s] = 1;
        do {
                pos = queue[head++];
                for (n = list[pos]; n != NULL; n = n->next) {
                        if (!visit[n->id]) {
                                if (n->id == t) return 1;
                                visit[n->id] = 1;
                                queue[tail++] = n->id;
                        }
                }
        } while (head != tail);
        return 0;
}

