void makeGroup(int s){
	int i,j,k,f;
	int qs=0, qe=0;
	queue[qe++] = s;
	while( qs < qe ){
		k = queue[qs++];
		for( i = 0; i < l[k].i; i++ ){
			f = l[k].friend[i];
