	}
	for( i = 0; i < m; i++ ){
		scanf("%d %d", &x, &y);
		if( l[x].i > 0 && l[x].i % MSIZE == 0 ){
			l[x].friend = (int*)realloc(l[x].friend, (l[x].i+MSIZE)*sizeof(int));
		}
		if( l[y].i > 0 && l[y].i % MSIZE == 0 ){
			l[y].friend = (int*)realloc(l[y].friend, (l[y].i+MSIZE)*sizeof(int));
		}
		l[x].friend[l[x].i] = y;
		l[y].friend[l[y].i] = x;
		l[x].i++;
		l[y].i++;
	}
	//make group.
	int temp = 0;
	for( i = 0; i < n; i++ ){
		if( l[i].group != -1 ){ continue; }
		l[i].group = temp++;
		makeGroup(i);
	}
	return;
}

