    for (i = 0; i < N ;++i) G[i] = i;
}

int find(int x) {
    if (x == G[x]) return x;
    return G[x] = find(G[x]);
}

int eq(int a, int b) {
    if(find(a) == find(b)) return 1;
    else return 0;
}

void cone(int a, int b) {
    a = find(a);
    b = find(b);

    if(a == b) return;
    G[b] = a;
}

