	scanf("%d %d", &n, &m);
	init(n, m);

	for(i = 0; i < m; ++i) {
		scanf("%d %d", &u, &v);
		add_edge(u, v);
		add_edge(v, u);
	}

	memset(label, -1, sizeof(label));
	for(i = 0; i < n; ++i) {
		if(label[i] == -1) bfs(i);
	}

	scanf("%d", &q);
	while(q--) {
		scanf("%d %d", &s, &t);
		puts(label[s] == label[t] ? "yes" : "no");
	}

	return EXIT_SUCCESS;
}

