#include <stdio.h>
#include <stdlib.h>

typedef struct _n {
  int id, visited;
  struct _n *next;
} node;

node *nodes;

void add(int origin_id, int direction_id) {
  node *p, *new;
  p = &nodes[origin_id];

  while(p->next != NULL)
    p = p->next;

  new = (node *)malloc(sizeof(node));
  p->next = new;
  new->id = direction_id;
}

int depthSearch(node *p, int direction_id) {
  if(p->id == direction_id) return 1;
  if(p->visited)
    return 0;
  else
    p->visited = 1;

  while(p->next != NULL) {
    p = p->next;
    if(p->id == direction_id)
      return 1;

    if(depthSearch(&nodes[p->id], direction_id)) return 1;
  }

  return 0;
}

int main() {
  int n, m;
  int i, j;
  int origin, direction;

  scanf("%d %d", &n, &m);
  nodes = calloc(n, sizeof(node));
  for(i = 0;i < n;i++) {
    nodes[i].id = i;
    nodes[i].visited = 0;
  }
  for(i = 0;i < m;i++) {
    scanf("%d %d", &origin, &direction);
    add(origin, direction);
    add(direction, origin);
  }

  scanf("%d", &n);
  for(i = 0;i < n;i++) {
    scanf("%d %d", &origin, &direction);
    depthSearch(&nodes[origin], direction) ? printf("yes\n") : printf("no\n");

    for(j = 0;j < n;j++)
      nodes[j].visited = 0;
  }

  return 0;
}

#include <stdio.h>
#define MAX 100000
#define WHITE 0
#define GRAY 1
#define BLACK 2
long int color[MAX];
long int memo[MAX];
long int v[MAX][MAX/100];

int dfs(long int u, long int t) {
   long int stack[MAX];
   long int i = 0;
   long int j;
   int judge = 0;
   stack[0] = u;
   color[u] = GRAY;
   while (stack[0] != -1) {
	  u = stack[i];
	  judge = 0;
	  if (memo[u] != 0) {
		 for (j = 0; j < memo[u]; ++j) {
			if (color[v[u][j]] == WHITE) {
			   color[v[u][j]] = GRAY;
			   stack[++i] = v[u][j];
			   if (v[u][j] == t)
				  return 1;
			   judge = 1;
			}
		 }
	  }
	  if (judge == 0) {
		 stack[i] = -1;
		 color[u] = BLACK;
		 --i;
	  }
   }
   return 0;
}

int CC(long int s, long int t, int n) {
   long int i;
   for (i = 0; i < n; ++i) {
	  color[i] = WHITE;
   }
   return dfs(s, t);
}

