int prim(){
    int u, minv;
    int d[100], p[100], color[100];

    for(i=0;i<n;i++){
        d[i] = 100000000;
        p[i] = -1;
        color[i] = WHITE;
    }
    d[0]=0;

    while(1){
        minv = 100000000;
        u = -1;
        for(i=0;i<n;i++){
            if(minv > d[i] && color[i] != BLACK){
                u = i;
                minv = d[i];
            }
        }
        if(u == -1)
        break;
        color[u]=BLACK;
        for(v=0;v<n;v++){
            if(color[v] != BLACK && M[u][v] != 100000000){
                if(d[v] > M[u][v]){
                    d[v] = M[u][v];
                    p[v] = u;
                    color[v] = GRAY;
                }
            }
        }
    }
    sum = 0;
    for(i=0;i<n;i++){
        if(p[i] != -1)
        sum += M[i][p[i]];
    }
    return sum;
}

