int BFS(int a, int b, int n, int m)
{
  int i, j, t, h, k, flag, r;
  int Q[100000], Z[10000];

  for( i = 0; i < 10000; i++ ) Z[i] = -1;
  for( i = 0; i < 100000; i++ ) Q[i] = -1;

  t = 0;
  for( i = 0; i < m; i++){
    for( j = 0; j <= 1; j++ ){
      if( a == G[i][j] ){
        if( j == 0 ) Q[t] = G[i][1];
        else Q[t] = G[i][0];
        Z[i] = 1;
        if( Q[t] == b ) {
          return 1;
          break;
        }
      }
    }
  }

  h = 0; r = 0; flag = 1;
  while(flag == 1){
    flag = 1;
    k = Q[t];
    t++;
    for( i = 0; i < m; i++ ){
      for( j = 0; j <= 1; j++ ){
        if( k == G[i][j] && Z[i] != 1 ){
         Z[i] = 1;
          if ( j == 0 ) {
            Q[h] = G[i][1];
            h++;
            if( G[i][1] == b ) {
              r = 1;
              break;
              flag = 0;
            }
          } else {
            Q[h] = G[i][0];
            h++;
            if( G[i][0] == b ) {
              r = 1;
              break;
              flag = 0;
            }
          }
        }
      }
    }
    if( Q[t] == -1 ) flag = 0;
  }

  if ( r == 1 ){
    return 1;
  } else {
    return 0;
  }
}



