  for(i=0;i<n;i++) p[i].numOfAdj=0;
  scanf("%d",&num);
  for(i=0;i<num;i++)
    {
      scanf("%d%d",&start,&end);
      setAdj(start,end);
      setAdj(end,start);
    }
  //printGraph();
  scanf("%d",&num);
  for(i=0;i<num;i++)
    {
      scanf("%d%d",&start,&end);
      if(breadthFirstSearch(start,end)!=-1) printf("yes\n");
      else printf("no\n");
    }
  return 0;
}
void setAdj(int start,int end)
{
  int i;//counter
  int *temp=p[start].adj;
  p[start].numOfAdj++;
  p[start].adj=(int*)malloc(sizeof(int)*p[start].numOfAdj);
  for(i=0;i<p[start].numOfAdj-1;i++) p[start].adj[i]=temp[i];
  p[start].adj[i]=end;
}
int breadthFirstSearch(int start,int end)
{
  int i;//counter
  int u,v;
  //printf("[%d->%d]\n",start,end);
  for(i=0;i<n;i++)
    {
      p[i].status=0;
      d[i]=-1;
    }
  queueReset();
  d[start]=0;
  enqueue(start);
  while(head!=tail)
    {
      u=dequeue();
      for(i=0;i<p[u].numOfAdj;i++)
        {
          v=p[u].adj[i];
          if(p[v].status==0)
            {
              //printf(" %d->%d\n",u,v);
              p[v].status=1;
              d[v]=d[u]+1;
              enqueue(v);
              if(v==end) return d[end];
            }
        }
      p[u].status=2;
    }
  return d[end];
}
void enqueue(int key)
{
  queue[tail]=key;
  tail++;
}
int dequeue(void)
{
  head++;
  return queue[head-1];
}
void queueReset(void)
{
  head=0;
  tail=0;
}
void printGraph(void)
{
  int i,j;//counter
  for(i=0;i<n;i++)
    {
      printf("[%d]",i);
      for(j=0;j<p[i].numOfAdj;j++) printf(", %d",p[i].adj[j]);
    }
}

