fun zAlgo(s: String): LongArray {
    val n = s.len
    val res = longAry(n)
    var i = 1L
    var j = 0L
    while(i < n) {
        while (i + j < n && s[j] == s[i + j]) j++
        res[i] = j
        if(j == 0L) {
            i++
            continue
        }
        var k = 1L
        while (i + k < n && k + res[k] < j) {
            res[i + k] = res[k]
            k++
        }
        i += k
        j -= k
    }

    return res
}


