                A.add(t);
                L.put(s,A);
            }
            if(L.containsKey(t)) L.get(t).add(s);
            else{
                ArrayList<Integer> A = new ArrayList<Integer>();
                A.add(s);
                L.put(t,A);
            }
        }
        //探索
        for(int i=0;i<n;i++){
            if(Con[i]==-1) {
                Con[i] = i;
                Connection(L, i, Con,i);
            }
        }
        L.clear();
