    public static void Connection(Map<Integer,ArrayList<Integer>> L,int now,int Con[],int cnt){
        ArrayDeque<Integer> Stack = new ArrayDeque<>();
        Stack.add(now);
        while(Stack.size()!=0){
            now = Stack.pop();
            if(L.get(now)!=null) {
                for(int i:L.get(now)){
                    if(Con[i] == -1){
                        Stack.add(i);
                        Con[i] = cnt;
                    }
                }
            }
        }
    }
