public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		Pair[] pairs = new Pair[m];
		for (int i = 0; i < m; i++) {
		    pairs[i] = new Pair(sc.nextInt(), sc.nextInt());
		}
		Arrays.sort(pairs);
		UnionFindTree uft = new UnionFindTree(n);
		for (int i = m - 1; i >= 0; i--) {
		    uft.unite(pairs[i]);
		}
		int q = sc.nextInt();
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < q; i++) {
		    if (uft.same(sc.nextInt(), sc.nextInt())) {
		        sb.append("yes");
		    } else {
		        sb.append("no");
		    }
		    sb.append("\n");
		}
		System.out.print(sb);
	}

	static class UnionFindTree {
	    int[] parents;

	    public UnionFindTree(int size) {
	        parents = new int[size];
	        for (int i = 0; i < size; i++) {
	            parents[i] = i;
	        }
	    }

	    public int find(int x) {
	        if (parents[x] == x) {
	            return x;
	        } else {
	            return parents[x] = find(parents[x]);
	        }
	    }

	    public boolean same(int x, int y) {
	        return find(x) == find(y);
	    }

	    public void unite(int x, int y) {
	        if (same(x, y)) {
	            return;
	        }
	        parents[find(x)] = find(y);
	        find(x);
	    }

	    public void unite(Pair p) {
	        unite(p.left, p.right);
	    }
	}

	static class Pair implements Comparable<Pair> {
	    int left;
	    int right;

	    public Pair(int x, int y) {
	        left = Math.min(x, y);
	        right = Math.max(x, y);
	    }

	    public int compareTo(Pair another) {
	        if (left == another.left) {
	            return right - another.right;
	        } else {
	            return left - another.left;
	        }
	    }
	}
}

import java.util.Scanner;

public class Main{

	public static Boolean networked(int start, int end, int[][] r, Boolean[] visited) {
		if(start == end) 
			return true;
		for(int i = 0; i < r.length; i++) {
			if(r[i][0] == start && !visited[i]) {
				visited[i] = true;
				return networked(r[i][1], end, r, visited);
			}
		}
		for(int i = 0; i < r.length; i++) {
			if(r[i][1] == start && !visited[i]) {
				visited[i] = true;
				return networked(r[i][0], end, r, visited);
			}
		}
		return false;
	}

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int verts = in.nextInt();
		int relations = in.nextInt();
		int[][] rel_array = new int[relations][2];
		for(int i = 0; i < relations; i++) {
			rel_array[i][0] = in.nextInt();
			rel_array[i][1] = in.nextInt();
		}
		int limit = in.nextInt();
		for(int i = 0; i < limit; i++) {
			Boolean[] visits = new Boolean[relations];
			for(int j = 0; j < relations; j++) {
				visits[j] = false;
			}
			if(networked(in.nextInt(), in.nextInt(), rel_array, visits) == true)
				System.out.println("yes");
			else System.out.println("no");
		}
		in.close();
	}

}

