			if (color[i] == -1) {
				dfs(list, i, id++);
			}
		}
	}

	public static void dfs(List<List<Integer>> list, int from, int id) {
		Stack<Integer> stack = new Stack<Integer>();
		int[] d = new int[list.size()];

		stack.push(from);
		color[from] = id;

		while (!stack.isEmpty()) {
			from = stack.peek();
			boolean isConnect = false;
			for (int to : list.get(from)) {
				if (color[to] != -1) {
					continue;
				}
				isConnect = true;
				stack.push(to);
				color[to] = id;
				break;
			}
			if (!isConnect) {
				stack.pop();
			}
		}

	}

