		for (int i=0; i < adjmatrix.length; i++) {
			if (adjmatrix[s][i] == 1) {
				if(i == t) return true;
				else if ( search(adjmatrix, i, t, issearched) ) {
					return true;
				}
			}
		}

		return false;
	}
