class Connection {
    int n;
    int[][] relationship;
    boolean[] followable;
    Connection (int n, int[][] relationship) {
	this.n = n;
	this.relationship = relationship;
	followable = new boolean[n];
    }

    public void makeFollowable () {
	int id = 1;
	for (int i = 0; i < n; i++) {
	    if (!followable[i]) {
		dfs(i, id++);
	    }
	}
    }

    public boolean isOK(int s, int t) {
	return followable[s] == followable[t];
    }

    public boolean dfs (int s, int t) {
	boolean[] done = new boolean[n];
	done[s] = true;
	ArrayDeque<Integer> stack = new ArrayDeque<Integer>();
	stack.push(s);
	while (stack.size() != 0) {
	    int u = stack.pop();
	    for (int i = 0; i < n; i++) {
		if (relationship[u][i] != 1) {
		    continue;
		}
		if (i == t) {
		    return true;
		}
		if (done[i] == false) {
		    done[i] = true;
		    stack.push(i);
		}
	    }
	}
	return false;
    }
}

