			V[s].adj.add(t);
			V[t].adj.add(s);
		}

		ArrayList<HashSet<Integer>> cmplist = new ArrayList<>();
		for(int i=0; i<n; i++) {
			if(V[i].d == -1) {
				V[i].d = 0;
				HashSet<Integer> cmp = new HashSet<>();
				cmp.add(i);
				V[i].breadthFirstSearch(cmp);
				cmplist.add(cmp);
			}
		}

