class Sns {

	int[][] friend;
	int[] size;
	int[] group;

	public Sns(int n) {
		friend = new int[n][100];
		size = new int[n];
		group = new int[n];
		for (int i = 0; i < n; i++)
			group[i] = -1;
	}

	public boolean isFriends(int s, int t) {
		if (group[s] == -1)
			setGroup(s);
		if (group[s] == group[t])
			return true;
		else
			return false;
	}

	private void setGroup(int s) {
		group[s] = s;
		int[] que = new int[group.length];
		que[0] = s;
		int pp = 0, pn = 1;
		for (; pp < pn; pp++) {
			for (int i = 0; i < size[que[pp]]; i++) {
				int next = friend[que[pp]][i];
				if (group[next] == -1) {
					group[next] = s;
					que[pn++] = next;
				}
			}
		}
	}

	public void add(int s, int t) {
		friend[s][size[s]++] = t;
		friend[t][size[t]++] = s;
	}

}

