class AOJ {

    final int N, M, Q;
    List<List<Integer>> list;
    int[] s, t, group;

    AOJ(FastScanner sc) {
        N = sc.nextInt();
        M = sc.nextInt();
        list = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            list.add(new ArrayList<>());
        }
        for (int i = 0; i < M; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            list.get(u).add(v);
            list.get(v).add(u);
        }
        Q = sc.nextInt();
        s = new int[Q];
        t = new int[Q];
        for (int i = 0; i < Q; i++) {
            s[i] = sc.nextInt();
            t[i] = sc.nextInt();
        }
        group = new int[N];
    }

    void solve(PrintWriter out) {
        groupingOfUsers();
        for (int i = 0; i < Q; i++) {
            out.println(group[s[i]] == group[t[i]] ? "yes" : "no");
        }
    }

    void groupingOfUsers() {
        int number = 1;
        for (int i = 0; i < N; i++) {
            if (group[i] == 0) {
                bfs(i, number);
                number++;
            }
        }
    }

    void bfs(int first_user, int number) {
        Deque<Integer> queue = new ArrayDeque<>();
        group[first_user] = number;
        queue.addLast(first_user);
        while (!queue.isEmpty()) {
            int this_user = queue.removeFirst();
            for (int i = 0; i < list.get(this_user).size(); i++) {
                int next_user = list.get(this_user).get(i);
                if (group[next_user] != 0) continue;
                group[next_user] = number;
                queue.addLast(next_user);
            }
        }
    }
}

