			for (int x : array)
				map.merge(x, 1, Integer::sum);
			return map;
		}
	}

	static class GraphUtils {
		public static boolean dfs(List<List<Integer>> list, int[] d, int index, int ser) {
			boolean flg = false;
			List<Integer> l = list.get(index);
			d[index] = 1;
			for (int i = 0; i < l.size() && !flg; i++) {
				int num = l.get(i);
				if (d[num] != -1) {
					continue;
				}
				d[num] = 1;
				if (num == ser) {
					return true;
				}
				flg = dfs(list, d, num, ser);
			}
			return flg;
		}
	}

