import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    static Scanner sc = new Scanner(System.in);
    static final int N = 100005;
    static final int UNVISITED = -1;
    static int n, m, q;
    static ArrayList<ArrayList<Integer>> G;
    static int[] c = new int[N];

    public static void main(String[] args) {
        read();
        for (int i = 0; i < n; i++) {
            dfs(i, i);
        }
        out();
    }

    static void init(int n) {
        G = new ArrayList<ArrayList<Integer>>(n);
        for (int i = 0; i < n; i++) {
            G.add(new ArrayList<Integer>());
            c[i] = UNVISITED;
        }
    }

    static void read() {
        n = sc.nextInt();
        m = sc.nextInt();

        init(n);

        int u, v;
        for (int i = 0; i < m; i++) {
            u = sc.nextInt();
            v = sc.nextInt();

            G.get(u).add(v);
            G.get(v).add(u);
        }

        q = sc.nextInt();
    }

    static void dfs(int v, int cls) {
        if (c[v] != UNVISITED) {
            return;
        }

        c[v] = cls;
        for (int i = 0; i < G.get(v).size(); i++) {
            dfs(G.get(v).get(i), cls);
        }
    }

    static void out() {
        int u, v;
        for (int i = 0; i < q; i++) {
            u = sc.nextInt();
            v = sc.nextInt();

            if (c[u] == c[v]) {
                System.out.println("yes");
            } else {
                System.out.println("no");
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

	static char list[][];
	static int status[];

	public static void main(String[] args) {
		Scanner in=new Scanner(System.in);
		int n=in.nextInt(), m=in.nextInt();list=new char[n][n];

		for(int i=0;i<m;i++) {
			int s=Integer.parseInt(in.next()), t=Integer.parseInt(in.next());
			list[s][t]=1; list[t][s]=1;
		}

		int q=in.nextInt();
		status=new int[n];
		PrintWriter out=new PrintWriter(System.out);
		for(int i=0;i<q;i++) {
			for(int j=0;j<n;j++)status[j]=0;
			int s=Integer.parseInt(in.next()), t=Integer.parseInt(in.next());
			if(solve(n,s,t))out.println("yes");
			else out.println("no");
		}
		out.flush();
	}

	static boolean solve(int n,int s, int t) {
		Queue<Integer> q=new ArrayDeque<>();
		q.add(s);
		status[s]=1;

		while(!q.isEmpty()) {
			int u=q.remove();
			for(int i=0;i<n;i++) {
				if(list[u][i]==1 && status[i]==0) {
					if(i==t)return true;
					status[i]=status[u]+1;
					q.add(i);
				}
			}
		}
		return false;
	}
}

