        for(int i = 0;i < n;i++){
            fin[i] = 0;
            k[i] = 0;
        }

        for(int i = 0;i < m;i++){
            a[i] = input.nextInt();
            b[i] = input.nextInt();
            k[a[i]]++;k[b[i]]++;
        }
        for(int i = 0;i < n;i++)
            graph[i] = new int[k[i]];

        for(int i = 0;i < m;i++){
            k[a[i]]--;k[b[i]]--;
            graph[a[i]][k[a[i]]] = b[i];
