					if (sns[x][i] && sns[i][y]) {
						r[x][y] = true;
						break;
					}
		boolean chg = false;
		for (int x = 0; x < n; x++)
			for (int y = 0; y < n; y++) {
				if (sns[x][y] ^ r[x][y])
					chg = true;
				sns[x][y] = r[x][y];
			}

		return chg;
	}

}

