class Sns {

	class Member {
		int[] friend = new int[10];
		int size = 0;
		int group = -1;

		public void addFr(int t) {
			friend[size++] = t;
		}
	}

	Member[] member;

	public Sns(int n) {
		member = new Member[n];
		for (int i = 0; i < n; i++)
			member[i] = new Member();
	}

	public boolean isFriends(int s, int t) {
		if (member[s].group == -1)
			setGroup(s);
		if (member[s].group == member[t].group)
			return true;
		else
			return false;
	}

	private void setGroup(int s) {
		member[s].group = s;
		int[] que = new int[member.length];
		que[0] = s;
		int pp = 0, pn = 1;
		for (; pp < pn; pp++) {
			for (int i = 0; i < member[que[pp]].size; i++) {
				int next = member[que[pp]].friend[i];
				if (member[next].group == -1) {
					member[next].group = s;
					que[pn++] = next;
				}
			}
		}
	}

	public void add(int s, int t) {
		member[s].addFr(t);
		member[t].addFr(s);
	}

}

import java.util.Scanner;
import java.util.ArrayList;
import java.util.Hashtable;
public class Main {
	public static void main(String[] args) {
		Scanner input = new Scanner(System.in);
		int nodes = input.nextInt();
		int connections = input.nextInt();
		Hashtable<Integer, ArrayList<Integer>> hash = new Hashtable<Integer, ArrayList<Integer>>();
		for(int i = 0; i < connections; i++) {
			int vertex = input.nextInt();
			int toVertex = input.nextInt();
			if(hash.containsKey(vertex)) {
				ArrayList<Integer> value = hash.get(vertex);
				value.add(toVertex);
				hash.put(vertex, value);
			}
			else {
				ArrayList<Integer> value = new ArrayList<Integer>();
				value.add(toVertex);
				hash.put(vertex, value);
			}
		}
		int tests = input.nextInt();
		int[][] testing = new int[tests][tests];
		for(int i = 0; i < tests; i++) {
			for(int j = 0; j < 2; j++) {
				testing[i][j] = input.nextInt();
			}
		}
		for(int i = 0; i < tests; i++) {
			boolean possible = viable(hash, testing[i][0], testing[i][1], new ArrayList<Integer>()) || 
					viable(hash, testing[i][1], testing[i][0], new ArrayList<Integer>());
			if(possible == true)
				System.out.println("yes");
			else
				System.out.println("no");
		}
	}
	public static boolean viable(Hashtable<Integer, ArrayList<Integer>> hash, int from, int to, ArrayList<Integer> checked) {
		if(checked.size() == hash.size())
			return false;
		if(hash.get(from) != null) {
			checked.add(from);
			if(hash.get(from).contains(to))
				return true;
			for(int i = 0; i < hash.get(from).size(); i++) {
				from = hash.get(from).get(i);
				return viable(hash, from, to, checked);
			}
		}else {
			return false;
		}
		return false;
	}
}

import java.util.Scanner;

public class Main {
public static class QuickUnionUF {

    private int[] id;

    public QuickUnionUF(int N) {
        id = new int[N];
        for (int i = 0; i < N; i++) {
            id[i] = i;
        }
    }

    public void union(int p, int q) {
        int i = root(p);
        int j = root(q);

        id[i] = j;
    }

    private int root(int i) {
        while (i != id[i])
            i = id[i];
        return i;
    }

    public boolean connected(int p, int q) {
        return root(p) == root(q);
    }
}

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int M = scanner.nextInt();
//        QuickFindUF uf = new QuickFindUF(N);
        QuickUnionUF uf = new QuickUnionUF(N);

        // input
        for (int i = 0; i < M; i++) {
            int p = scanner.nextInt();
            int q = scanner.nextInt();
            uf.union(p, q);
        }

        // Query
        int Q = scanner.nextInt();
        for (int i = 0; i < Q; i++) {
            int p = scanner.nextInt();
            int q = scanner.nextInt();
            if (uf.connected(p,q))
                System.out.print("yes\n");
            else
                System.out.print("no\n");
        }
    }
