	private void assiginColor() {
		Arrays.fill(color, -1);
		int id = 1;
		for (int i = 0; i < n; i++) {
			if (color[i] == -1)
				dfs(i, id++);
		}
	}

	private void dfs(int r, int c) {
		Deque<Integer> deque = new ArrayDeque<Integer>();
		deque.push(r);
		color[r] = c;
		while(!deque.isEmpty()){
			int u = deque.poll();
			for(int i = 0;i<G[u].size();i++){
				int v = G[u].get(i);
				if(color[v]==-1){
					color[v] = c;
					deque.push(v);
				}
			}
		}
	}
