class Connection {
    int n;
    int[][] relationship;
    int[] scc;
    Connection (int n, int[][] relationship) {
	this.n = n;
	this.relationship = relationship;
	scc = new int[n];
	for (int i = 0; i < n; i++) {
	    scc[i] = -1;
	}
    }

    public void makeFollowable () {
	int id = 1;
	for (int i = 0; i < n; i++) {
	    if (scc[i] == -1) {
		dfs(i, id++);
	    }
	}
    }

    public boolean isOK(int s, int t) {
	return scc[s] == scc[t];
    }

    public void dfs (int s, int t) {
	boolean[] done = new boolean[n];
	done[s] = true;
	ArrayDeque<Integer> stack = new ArrayDeque<Integer>();
	stack.push(s);
	scc[s] = t;
	while (stack.size() != 0) {
	    int u = stack.pop();
	    for (int i = 0; i < n; i++) {
		if (relationship[u][i] != 1) {
		    continue;
		}
		if (done[i] == false) {
		    done[i] = true;
		    stack.push(i);
		    scc[i] = t;
		}
	    }
	}
    }
}

