// With path compression and weights

public class Main {
	static int[] parent;
	static int[] weights;

	static void set(int x) {
		parent[x] = x;
		weights[x] = 1;
	}

	static void union(int x, int y) {
	    int a = find(x);
	    int b = find(y);
	    if(a != b) {
	    	if(weights[a] > weights[b]) {
	    		parent[b] = a;
	    		weights[a] += weights[b];
	    	} else {
	    		parent[a] = b;
	    		weights[b] += weights[a];
	    	}
	    }

	}

	static int find(int x) {
		 int curr = x;
		 if(parent[curr] == curr) return curr;
		 parent[curr] = find(parent[curr]);

		 return parent[curr];
		 // path compression
	}

	static boolean checkConnection(int x, int y) {
		return find(x) == find(y);
	}

	public static void main(String[] args) {

		//Set up Scanner
		Scanner in = new Scanner(System.in);

		//set up users
		int users = in.nextInt();

		// set up parent and weights
		parent = new int[users];
		weights = new int[users];
		int relations = in.nextInt();

		// set up parent
		parent = new int[users];

		//fill parent with reference to itself
		for(int i = 0; i < users; i++) {
			set(i);
		}

		//update unions in parent
		for(int i = 0; i < relations; i++) {
			union(in.nextInt(), in.nextInt());
		}

		int queries = in.nextInt();

		for (int i = 0; i < queries; i++) {
			int a = in.nextInt();
			int b = in.nextInt();
			if (checkConnection(a, b)) {
				System.out.println("yes");
			} else { 
				System.out.println("no");
			}
		}


		//close scanner
		in.close();

	}
}

import java.util.Scanner;

public class Main {

public static class QuickUnionUF {

    private int[] id;
    private int[] sz;

    public QuickUnionUF(int N) {
        id = new int[N];
        sz = new int[N];
        for (int i = 0; i < N; i++) {
            id[i] = i;
            sz[i] = 0;
        }
    }

    public void union(int p, int q) {
        int i = root(p);
        int j = root(q);

        if (i == j) return;
        if (sz[i] < sz[j]){
            id[i] = j;
            sz[j] += sz[i];
        }
        else {
            id[j] = i;
            sz[i] += sz[j];
        }
    }

    private int root(int i) {
        while (i != id[i])
            i = id[i];
        return i;
    }

    public boolean connected(int p, int q) {
        return root(p) == root(q);
    }
}


    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int M = scanner.nextInt();
//        QuickFindUF uf = new QuickFindUF(N);
        QuickUnionUF uf = new QuickUnionUF(N);

        // input
        for (int i = 0; i < M; i++) {
            int p = scanner.nextInt();
            int q = scanner.nextInt();
            uf.union(p, q);
        }

        // Query
        int Q = scanner.nextInt();
        for (int i = 0; i < Q; i++) {
            int p = scanner.nextInt();
            int q = scanner.nextInt();
            if (uf.connected(p,q))
                System.out.print("yes\n");
            else
                System.out.print("no\n");
        }
    }
}

