class Sns {

	int[] leader;

	public Sns(int n) {
		leader = new int[n];
		for (int i = 0; i < n; i++)
			leader[i] = i;
	}

	public boolean isFriends(int s, int t) {
		if (top(s) == top(t))
			return true;
		else
			return false;
	}

	private int top(int s) {
		if (leader[s] == s)
			return s;
		else
			return top(leader[s]);
	}

	public void addRel(int s, int t) {
		if (isFriends(s, t))
			return;
		leader[top(s)] = top(t);
	}

}

