					continue;
				}
				d[num] = 1;
				if (num == ser) {
					return true;
				}
				flg = dfs(list, d, num, ser);
			}
			return flg;
		}

		public static boolean bfs(List<List<Integer>> list, int from, int target) {
			boolean isFound = false;
			int[] d = new int[list.size()];
			Arrays.fill(d, -1);

			Deque<Integer> q = new ArrayDeque<Integer>();
			q.push(from);

			while (!q.isEmpty()) {
				int index = q.pop();
				d[index] = 1;
				for (int num : list.get(index)) {
					if (num == target) {
						isFound = true;
						return isFound;
					}
					if (d[num] == -1) {
						q.push(num);
					}
				}
			}
			return isFound;
		}
	}

