class Sns {
	class Member {
		List<Integer> friend = new ArrayList<Integer>();
	}

	Member[] member;

	public Sns(int n) {
		member = new Member[n];
		for (int i = 0; i < n; i++)
			member[i] = new Member();
	}

	public boolean isFriends(int s, int t) {
		boolean[] chk = new boolean[member.length];
		chk[s] = true;
		int[] que = new int[member.length];
		que[0] = s;
		int pp = 0, pn = 1;
		for (; pp < pn; pp++) {
			for (int i = 0; i < member[que[pp]].friend.size(); i++) {
				int next = member[que[pp]].friend.get(i);
				if (next == t)
					return true;
				if (!chk[next]) {
					chk[next] = true;
					que[pn++] = next;
				}
			}
		}
		return false;
	}

	public void add(int s, int t) {
		member[s].friend.add(t);
		member[t].friend.add(s);
	}

}

