					if(d[node] == false){
						if(node == frid){
							sb.append("yes\n");
							continue question;
						}
						// push the adjacent nodes
						d[pn] = true;
						st.push(node);
					}
				}
			}
			sb.append("no\n");
		}

		System.out.print(sb);
	}

}

