	static void solve(Stack<Integer> stk) {
		int u=stk.peek();
		status[u]=1;
		for(int i=0;i<status.length;i++) {
			if(list[u][i]==1 && status[i]!=1) {
				stk.push(i);
				solve(stk);
			}
		}
		stk.pop();
	}
