		boolean judge = false;

		dfs.clear();
		dfs.push(startnode);


		while (!(dfs.isEmpty())) {

			int now_node = dfs.pop();

			visied[now_node] = true;

			for (int i = 0; i < v[now_node].graph.size(); i++) {
				int next_node = v[now_node].graph.get(i);
