	public static void decompose(Node[] u,int id, int label) {
//		if (u[id].label != -1) return;
//		u[id].label = label;
//		for (int i=0; i < u[id].friends.size(); i++) {
//			int f = u[id].friends.get(i);
//			decompose(u, f, label);
//		}
		ArrayDeque<Integer> stack = new ArrayDeque<Integer>();
		stack.push(id);
		do {
			int index = stack.pop();
			if (u[index].label != -1) continue;
			u[index].label = label;
			for (int i=0; i < u[index].friends.size(); i++) {
				int friend = u[index].friends.get(i);
				stack.push(friend);
			}
		} while ( ! stack.isEmpty() );
	}

	public static class Node {
		int label;

		LinkedList<Integer> friends;

		public Node() {
			this.label = -1;
			this.friends = new LinkedList<>();
		}
	}

