		public static int readint() throws Exception {
			int c = System.in.read();

			while (spaceorenter(c)) {
				c = System.in.read();
			}

			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = System.in.read();
			}

			int n = 0;
			while (! spaceorenter(c)) {
				n = 10*n;
				n = n + c - '0';
				c = System.in.read();
			}

			return sgn * n;
		}

		private static boolean spaceorenter(int c) {
			return c == ' ' || c == '\n' || c == '\r';
		}
	}
