class Sns {
	class Member {
		List<Integer> friend = new ArrayList<Integer>();
	}

	Member[] member;

	public Sns(int n) {
		member = new Member[n];
		for (int i = 0; i < n; i++)
			member[i] = new Member();
	}

	public boolean isFriends(int s, int t) {
		boolean[] chk = new boolean[member.length];
		chk[s] = true;
		return isFr(s, t, chk);
	}

	private boolean isFr(int s, int t, boolean[] chk) {
		if (s == t)
			return true;
		for (int i = 0; i < member[s].friend.size(); i++) {
			int next = member[s].friend.get(i);
			if (!chk[next]) {
				chk[next] = true;
				if (isFr(next, t, chk))
					return true;
			}
		}
		return false;
	}

	public void add(int s, int t) {
		member[s].friend.add(t);
		member[t].friend.add(s);
	}

}

import java.util.*;

public class Main {

    static class Edge {
        int from, to;

        public Edge(int from, int to) {
            this.from = from;
            this.to = to;
        }
    }

    static class UnionFind {
        int[] size;
        int[] id;

        public UnionFind(int n) {
            size = new int[n];
            id = new int[n];

            for (int i = 0; i < n; ++i) {
                size[i] = 1;
                id[i] = i;
            }
        }

        void unify(int p, int q) {
            int root1 = find(p);
            int root2 = find(q);

            if (size[root1] > size[root2]) {
                size[root1] += size[root2];
                id[root2] = root1;
            } else {
                size[root2] += size[root1];
                id[root1] = root2;
            }
        }

        int find(int p) {
            int root = p;
            while (root != id[root]) root = id[root];
            while (p != root) {
                int next = id[p];
                id[p] = root;
                p = next;
            }
            return root;
        }

        boolean connected(int p, int q) {
            return find(p) == find(q);
        }
    }

    static int N, M, Q;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = Integer.parseInt(sc.next());
        M = Integer.parseInt(sc.next());
        UnionFind uf = new UnionFind(N);

        for (int i = 0; i < M; ++i) {
            uf.unify(Integer.parseInt(sc.next()), Integer.parseInt(sc.next()));
        }

        Q = Integer.parseInt(sc.next());
        for (int i = 0; i < Q; ++i) {
            if (uf.connected(sc.nextInt(),sc.nextInt()))
                System.out.println("yes");
            else
                System.out.println("no");
        }
    }
}

