class Sns{

		int[] leader;
		int[] member;

		public Sns(int n){
			leader = new int[n];
			member = new int[n];
			for(int i = 0; i < n; i++){
				leader[i] = i;
				member[i] = 1;
			}
		}

		public boolean isFriends(int s, int t){
			if(top(s) == top(t))
				return true;
			else
				return false;
		}
		private int top(int s){
			if(leader[s] == s)
				return s;
			else
				return top(leader[s]);
		}

		public void addRel(int s, int t){
			if(isFriends(s, t))
				return;
			int tt = top(t);
			int st = top(s);
			if(member[st] < member[tt]){
				leader[st] = tt;
				member[tt] += member[st];
			}else{
				leader[tt] = st;
				member[st] += member[tt];
			}
		}
}

