		}
		int q = in.nextInt();
		for (int i = 0; i < q; i++) {
			int from = in.nextInt();
			int to = in.nextInt();
			if (bfs(g, from, to)) {
				System.out.println("yes");
			} else {
				System.out.println("no");
			}
		}
	}
	public static boolean bfs(List<List<Integer>> list, int from, int target) {
		boolean isFound = false;
		int[] d = new int[list.size()];
		Arrays.fill(d, -1);

		Deque<Integer> q = new ArrayDeque<Integer>();
		q.push(from);

		while (!q.isEmpty()) {
			int index = q.pop();
			d[index] = 1;
			for (int num : list.get(index)) {
				if (num == target) {
					isFound = true;
					return isFound;
				}
				if (d[num] == -1) {
					q.push(num);
				}
			}
		}
		return isFound;
	}


	public static boolean dfs(List<List<Integer>> list, int[] d, int index, int target) {
		boolean flg = false;
		List<Integer> l = list.get(index);
		d[index] = 1;
		for (int i = 0; i < l.size() && !flg; i++) {
			int num = l.get(i);
			if (d[num] != -1) {
				continue;
			}
			d[num] = 1;
			if (num == target) {
				return true;
			}
			flg = dfs(list, d, num, target);
		}
		return flg;
	}
	public static boolean dfs2(List<List<Integer>> list, int from, int target) {
		boolean isFound = false;
		Stack<Integer> stack = new Stack<Integer>();
		int[] d = new int[list.size()];
		Arrays.fill(d, -1);

		stack.push(from);
		d[from] = 1;

		while (!stack.isEmpty()) {
			from = stack.pop();
			for (int to : list.get(from)) {
				if (to == target) {
					isFound = true;
					return isFound;
				}
				if (d[to] != -1) {
					continue;
				}
				stack.push(to);
				d[to] = 1;
				break;
			}
		}

		return isFound;
	}

}

