		public Graph(int n) {

			this.island = new int[n];
			this.matrix = new int[n][n];
			this.numEdge =0;
			this.mark =new int[n];
		}

		public int v() {
			return this.matrix.length;
		}

		public int e() {
			return this.numEdge;
		}

		public void setEdge(int i,int j) {
			this.matrix[i][j]=1;
			this.matrix[j][i]=1;
			this.numEdge++;
		}

		public void connected(int i,int j) {
			this.matrix[i][j]=1;
			this.matrix[j][i]=1;
			for (int a:this.getAdjecent(j)) {
				if (this.matrix[i][a]==0) {
					this.connected(i, a);
				}
			}
			for (int b:this.getAdjecent(i)) {
				if (this.matrix[j][b]==0) {
					this.connected(j, b);
				}
			}
		}

		public void delEdge(int i,int j) {
			this.matrix[i][j]=0;
			this.numEdge--;
		}

		public void setVisit(int ve) {
			this.mark[ve]=1;
		}

		public int getVisit(int ve) {
			return this.mark[ve];
		}

		public void reset() {
			this.mark=new int[this.v()];
		}

		public void setIsland(int a,int islandNum) {
			this.island[a] = islandNum; 
		}

		public void BFS(int a,int k) {
			Queue<Integer> q = new LinkedList<Integer>();
			q.offer(a);
		    this.setVisit(a);
		    this.setIsland(a, k);
		    while (!q.isEmpty()) {
		    	int m = q.poll();
		    	for (int i:this.getAdjecent(m)) {
		    		if (this.mark[i] ==0) {
		    			q.offer(i);
		    			this.setVisit(i);
		    			this.setIsland(i, k);
		    		}
		    	}
		    }
		}

		public void ConBFS() {
			int k=1;
			for (int i=0;i<this.v();i++) {
				if (this.mark[i]==0) {
					this.BFS(i, k);
					k++;
				}
			}
		}

		public ArrayList<Integer> getAdjecent(int ve){
			ArrayList<Integer> adj = new ArrayList<Integer>();
			for (int i =0;i<this.v();i++) {
				if (this.matrix[ve][i]==1) {
					adj.add(i);
				}
			}
			return adj;
		}
