			s = parseInt(line.substring(0, line.indexOf(' ')));
			t = parseInt(line.substring(line.indexOf(' ') + 1));
			G[s].es.add(G[t]);
			G[t].es.add(G[s]);
		}

		for (int i = 0; i < n; i++) {
			if (G[i].color == NIL) {
				G[i].color = color++;
				Deque<Vertex> stack = new ArrayDeque<>();
				stack.push(G[i]);
				while (!stack.isEmpty()) {
					Vertex s = stack.pop();
					for (Vertex t : s.es) {
						if (t.color == NIL) {
							t.color = G[i].color;
							stack.push(t);
						}
					}
				}
			}
		}


		int q = parseInt(br.readLine());
		StringBuilder sb = new StringBuilder();

		for (int i = 0; i < q; i++) {
			line = br.readLine();
			int s, t;
			s = parseInt(line.substring(0, line.indexOf(' ')));
			t = parseInt(line.substring(line.indexOf(' ') + 1));
			if (G[s].color == G[t].color) {
				sb.append("yes\n");
			} else {
				sb.append("no\n");
			}
		}

		System.out.print(sb.toString());
	}

	class Vertex {
		int color = NIL;
		List<Vertex> es = new ArrayList<>();
	}
}

