			nodes[t].Children.Add(nodes[s]);
		}

		int q = int.Parse(Console.ReadLine());
		for(int i = 0; i < q; i++) {
			Initialize(nodes);

			tmp = Array.ConvertAll(Console.ReadLine().Split(" ".ToCharArray()), int.Parse);
			int s = tmp[0];
			int t = tmp [1];
			BFS(nodes[s], nodes[t], nodes[s].Children.ToArray());
			Console.WriteLine( (nodes[t].d != -1)? "yes" : "no" );
		}
	}

	static void Initialize(Node[] nodes)
	{
		foreach(var node in nodes) {
			node.d = 0;
			node.Added = false;
		}
	}

	static void BFS(Node start, Node goal,Node[] onWays)
	{
		if(start == goal) return;
		else {
			goal.d++;

			List<Node> nexts = new List<Node>();
			foreach (var o in onWays) {
				if(o == goal) return;

				if(!o.Added) {
					foreach(Node p in o.Children.ToArray()){
						if(p != start) nexts.Add(p);
					}
					o.Added = true;
				}
			}
			if(nexts.Count != 0) BFS(start, goal, nexts.ToArray());
			else goal.d = -1;
		}
	}

}

