    class User
    {
        internal bool isCheck;
        internal List<int> friends;

        public User()
        {
            isCheck = false;
            friends = new List<int>();
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            int[] input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
            int n = input[0], m = input[1];

            User[] users = new User[n];
            for (int i = 0; i < n; i++) users[i] = new User();

            for (int i = 0; i < m; i++)
            {
                input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                int a = input[0], b = input[1];

                users[a].friends.Add(b);
                users[b].friends.Add(a);
            }

            StringBuilder sb = new StringBuilder();
            int q = int.Parse(Console.ReadLine());

            for (int i = 0; i < q; i++)
            {
                if (i != 0)
                {
                    for (int j = 0; j < n; j++) users[j].isCheck = false;
                }

                input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                int s = input[0], t = input[1];

                sb.AppendLine(isFriend(users, s, t) ? "yes" : "no");
            }
            Console.Write(sb);
        }

        static bool isFriend(User[] u, int s, int t)
        {
            Stack<int> stk = new Stack<int>();
            u[s].isCheck = true;
            stk.Push(s);

            while (stk.Count > 0)
            {
                int temp = stk.Pop();

                for (int i = 0; i < u[temp].friends.Count; i++)
                {
                    int v = u[temp].friends[i];

                    if (v == t) return true;

                    if (!u[v].isCheck)
                    {
                        u[v].isCheck = true;
                        stk.Push(v);
                    }
                }
            }
            return false;
        }
    }
}

