namespace Graph_I
{
    class Connected_Components
    {
        static bool[,] isConnected;

        static void Main(string[] args)
        {
            var nm = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
            var n = nm[0];
            var m = nm[1];
            var G = new bool[n, n];
            isConnected = new bool[n, n];

            for (int i = 0; i < m; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                var s = st[0];
                var t = st[1];
                G[s, t] = G[t, s] = true;
            }

            var q = int.Parse(Console.ReadLine());

            var str = new StringBuilder();
            for (int i = 0; i < q; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                if (BreadthFirstSearch(G, st[0], st[1])) str.Append("yes\n");
                else str.Append("no\n");
            }

            Console.Write(str.ToString());
        }

        static bool BreadthFirstSearch(bool[,] graph, int departure, int destination)
        {
            if (isConnected[departure, destination]) return true;
            var n = graph.GetLength(0);
            var done = new bool[n];
            var queue = new Queue<int>();

            done[departure] = true;
            queue.Enqueue(departure);

            while (queue.Count > 0)
            {
                var r = queue.Dequeue();
                if (r == destination) return true;
                for (int i = 0; i < n; i++)
                {
                    if (graph[r, i] && !done[i])
                    {
                        done[i] = true;
                        isConnected[departure, i] = isConnected[i, departure] = true;
                        queue.Enqueue(i);
                    }
                }
            }
            return false;
        }
    }
}

