namespace ALDS1_11D{
    public class Program{
        public static void Main(string[] args){
            var sr = new StreamReader();
            //---------------------------------
            var N = sr.Next<int>();

            var g = new List<int>[N];
            for(var i = 0; i < N; i++){
                g[i] = new List<int>();
            }

            var M = sr.Next<int>();
            for(var i = 0; i < M; i++){
                var S = sr.Next<int>();
                var T = sr.Next<int>();
                g[S].Add(T);
                g[T].Add(S);
            }

            var Q = sr.Next<int>();

            Func<int, int, bool> bfs = (s, t) =>{
                var visit = new bool[N];
                var que = new Queue<int>();
                visit[s] = true;
                que.Enqueue(s);

                while(que.Count > 0){
                    var now = que.Dequeue();
                    foreach(var next in g[now]){
                        if(visit[next]) continue;
                        if(next == t) return true;

                        visit[next] = true;
                        que.Enqueue(next);
                    }
                }

                return false;
            };

            for(var i = 0; i < Q; i++){
                var S = sr.Next<int>();
                var T = sr.Next<int>();
                Console.WriteLine(bfs(S, T) ? "yes" : "no");
            }
            //---------------------------------
        }
    }

    public class StreamReader{
        private readonly char[] _c = {' '};
        private int _index = -1;
        private string[] _input = new string[0];

        public T Next<T>(){
            if(_index == _input.Length - 1){
                _index = -1;
                while(true){
                    string rl = Console.ReadLine();
                    if(rl == null){
                        if(typeof(T).IsClass) return default(T);
                        return (T)typeof(T).GetField("MinValue").GetValue(null);
                    }
                    if(rl != ""){
                        _input = rl.Split(_c, StringSplitOptions.RemoveEmptyEntries);
                        break;
                    }
                }
            }
            return (T)Convert.ChangeType(_input[++_index], typeof(T), System.Globalization.CultureInfo.InvariantCulture);
        }
    }
}

