    private TreeNode[] TreeList;
    private class TreeNode {
        public TreeNode Parent;
        private TreeNode Root;
        public List<TreeNode> Items = new List<TreeNode>();
        public int ID;

        public TreeNode GetRoot() {
            if(this.Parent == null) {
                return this;
            }
            if(this.Root != null) {
                return this.Root;
            }
            this.Root = this.Parent.GetRoot();
            return this.Root;
        }

        public void SetRoot(TreeNode r) {
            this.Root = r;
            this.Items.ForEach(a=>a.SetRoot(r));
        }
        public TreeNode(int id) {
            this.ID = id;
        }

        public void Add(TreeNode cld) {
            this.Items.Add(cld);
            cld.Parent = this;
        }

        public void UpsideDown() {
            if(this.Parent == null) {
                return;
            }
            TreeNode tmp = this.Parent;
            tmp.Items.Remove(this);
            this.Parent = null;
            tmp.UpsideDown();
            this.Add(tmp);
        }
    }





