using System.Linq;
using System.Text;

namespace ConsoleApplication1
{
    class UnionFindNode
    {
        internal UnionFindNode parent;
        internal int rank;
    }

    class UnionFind
    {
        Dictionary<object, UnionFindNode> _dict;

        public UnionFind()
        {
            _dict = new Dictionary<object, UnionFindNode>();
        }

        public void Unite(IComparable x, IComparable y)
        {
            var xRoot = Root(x);
            var yRoot = Root(y);

            if (xRoot == yRoot) return;

            if (xRoot.rank < yRoot.rank)
            {
                xRoot.parent = yRoot;
            }
            else
            {
                yRoot.parent = xRoot;

                if (xRoot.rank == yRoot.rank) xRoot.rank++;
            }
        }

        public bool IsSame(IComparable x, IComparable y)
        {
            return Root(x) == Root(y);
        }

        UnionFindNode Root(object obj)
        {
            if (!_dict.ContainsKey(obj))
            {
                var node = new UnionFindNode();
                _dict.Add(obj, node);
                return node;
            }
            else
            {
                var node = _dict[obj];
                return Find(node);
            }
        }

        UnionFindNode Find(UnionFindNode node)
        {
            if (node.parent == null) return node;

            return node.parent = Find(node.parent);
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int m = int.Parse(input[1]);

            UnionFind uf = new UnionFind();

            for(int i = 0; i < m; i++)
            {
                input = Console.ReadLine().Split(' ');
                int x = int.Parse(input[0]);
                int y = int.Parse(input[1]);

                uf.Unite(x, y);
            }

            int q = int.Parse(Console.ReadLine());

            StringBuilder sb = new StringBuilder();
            for(int i = 0; i < q; i++)
            {
                input = Console.ReadLine().Split(' ');
                int x = int.Parse(input[0]);
                int y = int.Parse(input[1]);

                sb.AppendLine(uf.IsSame(x, y) ? "yes" : "no");
            }
            Console.Write(sb);
        }
    }
}

