class Program{
    class Connection{
        public int s;
        public int t;
    }

    static void Merge(Connection[] connections, int left, int mid, int right){
        var n1=mid-left;
        var n2=right-mid;
        var l=new Connection[n1+1];
        var r=new Connection[n2+1];
        for (var i=0; i<n1; i++) {
            l[i]=connections[left+i];
        }
        for (var i=0; i<n2; i++) {
            r[i]=connections[mid+i];
        }
        l[n1]=new Connection();
        l[n1].s=100*1000+1;
        l[n1].t=100*1000+1;
        r[n2]=new Connection();
        r[n2].s=100*1000+1;
        r[n2].t=100*1000+1;

        var ll=0;
        var rr=0;
        for (var k=left; k<right; k++) {
            if (l[ll].s==r[rr].s) {
                if (l[ll].t<=r[rr].t) {
                    connections[k]=l[ll];
                    ll++;
                } else {
                    connections[k]=r[rr];
                    rr++;
                }
            } else{
                if (l[ll].s<=r[rr].s) {
                    connections[k]=l[ll];
                    ll++;
                } else {
                    connections[k]=r[rr];
                    rr++;
                }
            }
        }
    }

    static void MergeSort(Connection[] connections, int left, int right){
        if (left+1<right) {
            var mid=(left+right)/2;
            MergeSort(connections, left, mid);
            MergeSort(connections, mid, right);
            Merge(connections, left, mid, right);
        }
    }

    public static void Main(){
        var s=Console.ReadLine().Split(' ');
        var n=int.Parse(s[0]);
