            var user1=int.Parse(s[0]);
            var user2=int.Parse(s[1]);
            if (user1<user2) {
                connections[i].s=user1;
                connections[i].t=user2;
            } else {
                connections[i].s=user2;
                connections[i].t=user1;
            }
        }

        MergeSort(connections, 0, m);
        var group=new int[n];
        for (var i=0; i<n; i++) {
            group[i]=i;
        }
        for (var i=0; i<m; i++) {
            group[connections[i].t]=group[connections[i].s];
