    class Program
    {
        static void Main(string[] args)
        {
            int[] input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
            int n = input[0], m = input[1];

            List<List<int>> table = new List<List<int>>();
            int[] group = new int[n];
            for (int i = 0; i < n; i++)
            {
                table.Add(new List<int>());
                group[i] = -1;
            }

            for (int i = 0; i < m; i++)
            {
                input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                table[input[0]].Add(input[1]);
                table[input[1]].Add(input[0]);
            }

            for (int i = 0, g = 0; i < n; i++)
            {
                if (group[i] == -1) DFS(table, group, i, g++);
            }

            StringBuilder sb = new StringBuilder();
            int q = int.Parse(Console.ReadLine());

            for (int i = 0; i < q; i++)
            {
                input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                sb.AppendLine(group[input[0]] == group[input[1]] ? "yes" : "no");
            }
            Console.Write(sb);
        }

        static void DFS(List<List<int>> table, int[] group, int u, int g)
        {
            Stack<int> stk = new Stack<int>();
            group[u] = g;
            stk.Push(u);

            while (stk.Count > 0)
            {
                int temp = stk.Pop();

                foreach (var friend in table[temp])
                {
                    if (group[friend] == -1)
                    {
                        group[friend] = g;
                        stk.Push(friend);
                    }
                }
            }
        }
    }
}

