			=> X.Indices(0).Select(
				i => X.Indices(1).Select(j => X[i, j]).Join(separatorD2)
			).Join(separatorD1);
	}
	class ConsoleInput {
		private readonly TextReader _stream;
		private readonly char _separator = ' ';
		private readonly Queue<string> inputStream;
		public ConsoleInput(TextReader stream, char separator = ' ') {
			this._separator=separator;
			this._stream=stream;
			inputStream=new Queue<string>();
		}
		public string Read {
			get {
				if(inputStream.Count!=0) return inputStream.Dequeue();
				string[] tmp = _stream.ReadLine().Split(_separator);
				for(int i = 0; i<tmp.Length; ++i)
					inputStream.Enqueue(tmp[i]);
				return inputStream.Dequeue();
			}
		}
		public string ReadLine { get { return _stream.ReadLine(); } }
		public int ReadInt { get { return int.Parse(Read); } }
		public long ReadLong { get { return long.Parse(Read); } }
		public double ReadDouble { get { return double.Parse(Read); } }
		public string[] ReadStrArray(long N) {
			var ret = new string[N];
			for(long i = 0; i<N; ++i)
				ret[i]=Read;
			return ret;
		}
		public int[] ReadIntArray(long N) { var ret = new int[N]; for(long i = 0; i<N; ++i) ret[i]=ReadInt; return ret; }
		public long[] ReadLongArray(long N) { var ret = new long[N]; for(long i = 0; i<N; ++i) ret[i]=ReadLong; return ret; }
		public double[] ReadDoubleArray(long N) { var ret = new double[N]; for(long i = 0; i<N; ++i) ret[i]=ReadDouble; return ret; }
		public bool isEOF {
			get { return _stream.Peek()==-1; }
		}
	}
	class UnionFindForest {
		public class Node {
			public int value { get; set; }
			public Node parent { get; set; }
			public Node root {
				get {
					var path = new Queue<Node>();
					var res = this;
					while(res.parent!=res) {
						path.Enqueue(res);
						res=res.parent;
					}
					while(path.Any())
						path.Dequeue().parent=res;
					return res;
				}
			}
			public int rank { get; private set; }    //meanful iff this is root
			public void rankIncrement() => rank++;
			public Node(int thisValue) {
				value=thisValue;
				parent=this;
				rank=1;
			}
		}

		private readonly Dictionary<int, Node> phoneBook = new Dictionary<int, Node>();
		public void Union(int x, int y) => Union(phoneBook[x], phoneBook[y]);
		public void Union(Node X, Node Y) {
			var RX = X.root;
			var RY = Y.root;
			switch(RX.rank.CompareTo(RY.rank)) {
				case 1:
					RY.parent=RX;
					break;
				case -1:
					RX.parent=RY;
					break;
				default:
					RX.parent=RY;
					RY.rankIncrement();
					break;
			}
		}
		public bool Find(int x, int y) => Find(phoneBook[x], phoneBook[y]);
		public bool Find(Node X, Node Y) => X.root==Y.root;
		public void Add(int id) {
			var N = new Node(id);
			phoneBook.Add(id, N);
		}
	}
}

