        for (int i = 0; i < n; i++)
        {
            if (g[i].Group != -1)
            {
                continue;
            }
            group++;
            q.Enqueue(i);
            g[i].Group = group;
            Bfs(group, g, q);
        }

        int qNum = int.Parse(Console.ReadLine());

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < qNum; i++)
        {
            int[] val = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            if (g[val[0]].Group == g[val[1]].Group)
            {
                sb.Append("yes");
            }
            else
            {
                sb.Append("no");
            }
            sb.AppendLine();
        }
        Console.Write(sb.ToString());
    }

    public static void Bfs(int group, Node[] g, Queue<int> queue)
    {
        while (queue.Count > 0)
        {
            var i = queue.Dequeue();
            for (int j = 0; j < g[i].Adj.Count; j++)
            {
                if (g[g[i].Adj[j]].Group == -1)
                {
                    g[g[i].Adj[j]].Group = group;
                    queue.Enqueue(g[i].Adj[j]);
                }
            }
        }
    }
}

