		int n = tmp[0];
		int m = tmp[1];

		Node[] nodes = new Node[n];
		for(int i = 0; i < n; i++) {
			nodes[i] = new Node(i);
		}
		color = new int[n];

		for(int i = 0; i < m; i++) {
			tmp = Array.ConvertAll(Console.ReadLine().Split(" ".ToCharArray()), int.Parse);
			int s = tmp[0];
			int t = tmp [1];

			nodes[s].Children.Add(nodes[t]);
			nodes[t].Children.Add(nodes[s]);
		}

		AssignColor(nodes);

		int q = int.Parse(Console.ReadLine());
		StringBuilder sb = new StringBuilder();
		for(int i = 0; i < q; i++) {

			tmp = Array.ConvertAll(Console.ReadLine().Split(" ".ToCharArray()), int.Parse);
			int s = tmp[0];
			int t = tmp [1];

			sb.AppendLine( (color[s] == color[t])? "yes" : "no" );
		}
		Console.Write(sb);
	}

	static void AssignColor(Node[] nodes)
	{
		int rootId = 0;

		for(int i = 0; i < nodes.Length; i++) {
			if(color[i] == 0) DFS(nodes[i], ++rootId);
		}
	}

	static void DFS(Node r, int c)
	{
		var S = new Stack<Node>();

		S.Push(r);
		color[r.Id] = c;

		while(S.Any())
		{
			Node u = S.Pop();

			foreach (var d  in u.Children) {
				if(color[d.Id] == 0) { 
					S.Push(d);
					color[d.Id] = c;
				}
			}
		}
	}
}

