        public static int Root(int x)
        {
            if (connectTree[x] == x) return x;
            else return connectTree[x] = Root(connectTree[x]);
        }

        public static void Connect(int x, int y)
        {
            if (IsConnected(x, y)) return;

            if (height[x] < height[y])
                connectTree[x] = y;
            else
            {
                connectTree[y] = x;
                if (height[x] == height[y]) height[x]++;
            }
        }

        public static bool IsConnected(int x, int y) => Root(x) == Root(y);

