	class Gragh
	{
		public Gragh ( int size )
		{
			this.Size = size;
			this.AdjacencyList = new List<int>[this.Size];

			int capacity = 2;
			for (int lp = 0; lp < this.Size; lp++)
			{
				this.AdjacencyList[lp] = new List<int> (capacity);
			}

			this.Group = new int[this.Size];
		}

		private List<int>[] AdjacencyList { set; get; }
		private int Size { set; get; }
		private int[] Group { set; get; }
		private const int Initialize = 0;

		private const int NotVisited = 0;
		private const int Stay = 1;
		private const int Visited = 2;

		public void GetPath ( int beginPoint, int adjacencyPoint )
		{
			AdjacencyList[beginPoint].Add (adjacencyPoint);
			AdjacencyList[adjacencyPoint].Add (beginPoint);
		}

		public void SetRoot ()
		{
			int groupNumber = Initialize + 1;

			for (int lp = 0; lp < Size; lp++)
			{
				if (Group[lp] == Initialize)
				{
					BreathFirstSearch (lp, groupNumber);
					groupNumber++;
				}
			}
		}

		private void BreathFirstSearch ( int beginSearchPoint, int groupNumber )
		{
			//initialize
			Queue<int> searchPoint = new Queue<int> (Size / 10);
			int[] visitState = new int[Size];

			//process
			searchPoint.Enqueue (beginSearchPoint);

			while (searchPoint.Count != 0)
			{
				int element = searchPoint.Dequeue ();
				visitState[element] = Visited;

				foreach (var item in AdjacencyList[element])
				{
					Group[item] = groupNumber;

					if (visitState[item] == NotVisited)
					{
						searchPoint.Enqueue (item);
						visitState[item] = Stay;
					}
				}
			}
		}

		public bool IsAdjacency ( int beginPoint, int adjacencyPoint )
		{
			return Group[beginPoint] == Group[adjacencyPoint] && Group[beginPoint] != Initialize;
		}
	}
