        static Dictionary<int, int> link;

        static void Main(string[] args)
        {
            var nm = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
            var n = nm[0];
            var m = nm[1];
            Cycle = Enumerable.Range(0, n).ToArray();
            isConnect = new bool[n];
            link = new Dictionary<int, int>();
            connectList = Enumerable.Range(0, n).ToArray();

            for (int i = 0; i < m; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                var s = st[0];
                var t = st[1];
                Connect(s, t);
            }

            var q = int.Parse(Console.ReadLine());

            var str = new StringBuilder();
            for (int i = 0; i < q; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                str.AppendLine((IsConnect(st[0], st[1]) ? "yes" : "no"));
            }

            Console.Write(str.ToString());
        }

        static void Connect(int s, int t)
        {
            if (IsConnect(s, t)) return;

            if (!isConnect[s]) connectList[s] = connectList[t];
            else if (!isConnect[t]) connectList[t] = connectList[s];

            isConnect[s] = isConnect[t] = true;
        }

        static bool IsConnect(int s, int t)
        {
            if (connectList[s] == connectList[t]) return true;

            int min, max;
            if (s < t)
            {
                if (link.ContainsKey(s)) { min = link[s]; max = t; }
                else return false;
            }
            else
            {
                if (link.ContainsKey(t)) { min = link[t]; max = s; }
                else return false;
            }

            while (true)
            {
                if (min == max) return true;
                if (link.ContainsKey(min)) min = link[min];
                else return false;
            }
        }
    }
