	}

	static void DFS(Node r, Node c)
	{
		var S = new Stack<Node>();

		S.Push(r);
		color[r.Id] = c.Id;

		while(S.Any())
		{
			Node u = S.Pop();

			foreach (var d  in u.Children) {
				if(color[d.Id] == 0) { 
					S.Push(d);
					color[d.Id] = c.Id;
				}
			}
		}
	}
}

