namespace Graph_I
{
    class Connected_Components
    {
        static bool[,] isConnected;

        static void Main(string[] args)
        {
            var nm = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
            var n = nm[0];
            var m = nm[1];
            var G = new bool[n, n];
            isConnected = new bool[n, n];

            for (int i = 0; i < m; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                var s = st[0];
                var t = st[1];
                G[s, t] = G[t, s] = true;
            }

            SearchConnect(G);

            var q = int.Parse(Console.ReadLine());

            var str = new StringBuilder();
            for (int i = 0; i < q; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                if (isConnected[st[0], st[1]]) str.Append("yes\n");
                else str.Append("no\n");
            }

            Console.Write(str.ToString());
        }

        static void SearchConnect(bool[,] graph)
        {
            var n = graph.GetLength(0);

            var done = new bool[n];

            for (int k = 0; k < n; k++)
            {
                if (!done[k])
                {
                    var queue = new Queue<int>();
                    var connectlist = new List<int>();
                    queue.Enqueue(k);
                    connectlist.Add(k);

                    while (queue.Count > 0)
                    {
                        var r = queue.Dequeue();
                        for (int i = 0; i < n; i++)
                        {
                            if (graph[r, i] && !done[i])
                            {
                                connectlist.Add(i);
                                queue.Enqueue(i);
                                done[i] = true;
                            }
                        }
                    }

                    var l = connectlist.Count;
                    for (int i = 0; i < l; i++)
                    {
                        for (int j = i; j < l; j++)
                        {
                            isConnected[connectlist[i], connectlist[j]] = isConnected[connectlist[j], connectlist[i]] = true;
                        }
                    }
                }
            }
        }
    }
}

