public static class Program {
    private static int[] arr;
    enum C {
        B,W,G
    }
    public static void Main() {
        #region SetAutoFlushIsFalse
#if !DEBUG
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
#endif
        #endregion
        var max = 100000;
        var lists = new List<int>[max+1];
        for (int i = 0; i < lists.Count(); i++) {
            lists[i] = new List<int>();
        }

        while (true) {
            arr = ReadLib.ReadAsIntArray();    
            if (arr.Length == 1) {
                break;
            }

            lists[arr[0]].Add(arr[1]);
            lists[arr[1]].Add(arr[0]);
        }

        var n = arr[0];
        var groups = Enumerable.Repeat(-1, max + 1).ToArray();
        var colors = Enumerable.Repeat(C.W, max + 1).ToArray();
        var gCnt = 0;
        // 幅優先で
        for (int i = 0; i < lists.Length; i++) {
            if (groups[i] != -1) {
                continue;
            }

            // BFS
            var q = new Queue<int>();
            gCnt++;
            groups[i] = gCnt;
            q.Enqueue(i);
            colors[i] = C.G;
            while (q.Count > 0) {
                var id = q.Dequeue();
                foreach (var cand in lists[id]) {
                    if (colors[cand] == C.W) {
                        colors[cand] = C.G;
                        groups[cand] = gCnt;
                        q.Enqueue(cand);
                    }
                }

                colors[id] = C.B;
            }
        }

        for (int i = 0; i < n; i++) {
            var arr = ReadLib.ReadAsIntArray();
            Console.WriteLine(groups[arr[0]] == groups[arr[1]] ? "yes" : "no");
        }

        #region Flush
#if !DEBUG
        Console.Out.Flush();
        sw.Close();
#endif
        #endregion
    }
}

