namespace ALDS1_11_D_ConnectedComponents
{
	class Program
	{
		static void Main ( string[] args )
		{
			int[] inputNum = Array.ConvertAll (Console.ReadLine ().Split (' '), int.Parse);
			Gragh graph = new Gragh (inputNum[0]);

			for (int lp = 0; lp < inputNum[1]; lp++)
			{
				int[] adjacencyPair = Array.ConvertAll (Console.ReadLine ().Split (' '), int.Parse);

				graph.GetPath (adjacencyPair[0], adjacencyPair[1]);
			}

			graph.SetRoot ();

			int judgeCount = int.Parse (Console.ReadLine ());
			StringBuilder output = new StringBuilder (3 * judgeCount);

			for (int lp = 0; lp < judgeCount; lp++)
			{
				int[] adjacencyPair = Array.ConvertAll (Console.ReadLine ().Split (' '), int.Parse);

				if (graph.IsAdjacency (adjacencyPair[0], adjacencyPair[1]))
				{
					output.AppendLine ("yes");
				}
				else
				{
					output.AppendLine ("no");
				}
			}

			Console.Write (output);
		}
	}

	class Gragh
	{
		public Gragh ( int size )
		{
			this.Size = size;
			this.AdjacencyList = new List<int>[this.Size];

			int capacity = this.Size / 10;
			for (int lp = 0; lp < this.Size; lp++)
			{
				this.AdjacencyList[lp] = new List<int> (capacity);
			}

			this.Group = new int[this.Size];
		}

		private List<int>[] AdjacencyList { set; get; }
		private int Size { set; get; }
		private int[] Group { set; get; }
		private const int Initialize = 0;

		private enum State
		{
			NotVisited, Stay, Visited
		};

		public void GetPath ( int beginPoint, int adjacencyPoint )
		{
			AdjacencyList[beginPoint].Add (adjacencyPoint);
			AdjacencyList[adjacencyPoint].Add (beginPoint);
		}

		public void SetRoot ()
		{
			int groupNumber = Initialize + 1;

			for (int lp = 0; lp < Size; lp++)
			{
				if (Group[lp] == Initialize)
				{
					BreathFirstSearch (lp, groupNumber);
					groupNumber++;
				}
			}
		}

		private void BreathFirstSearch ( int beginSearchPoint, int groupNumber )
		{
			//initialize
			Queue<int> searchPoint = new Queue<int> (Size / 10);
			State[] visitState = Enumerable.Repeat (State.NotVisited, Size).ToArray ();

			//process
			searchPoint.Enqueue (beginSearchPoint);

			while (searchPoint.Count != 0)
			{
				int element = searchPoint.Dequeue ();
				visitState[element] = State.Visited;

				foreach (var item in AdjacencyList[element])
				{
					Group[item] = groupNumber;

					if (visitState[item] == State.NotVisited)
					{
						searchPoint.Enqueue (item);
						visitState[item] = State.Stay;
					}
				}
			}
		}

		public bool IsAdjacency ( int beginPoint, int adjacencyPoint )
		{
			bool isSame = Group[beginPoint] == Group[adjacencyPoint];
			bool isJoin = Group[beginPoint] != Initialize;

			return isSame && isJoin;
		}
	}
}

