        static void Connect(int s, int t)
        {
            if (IsConnect(s, t)) return;

            var sp = Cycle[s];
            while (true)
            {
                if (Cycle[sp] == s) break;
                sp = Cycle[sp];
            }
            Cycle[sp] = t;
            Cycle[t] = s;
        }

        static bool IsConnect(int s, int t)
        {
            int sp = s;
            while ((sp = Cycle[sp]) != s)
                if (sp == t) return true;

            return false;
        }
    }
