            var m = nm[1];
            var G = new bool[n, n];

            for (int i = 0; i < m; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                var s = st[0];
                var t = st[1];
                G[s, t] = G[t, s] = true;
            }

            var q = int.Parse(Console.ReadLine());

            var str = new StringBuilder();
            for (int i = 0; i < q; i++)
            {
                var st = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
                if (BreadthFirstSearch(G, st[0], st[1]) != -1) str.Append("yes\n");
                else str.Append("no\n");
            }

            Console.Write(str.ToString());
        }

        static int BreadthFirstSearch(bool[,] graph, int departure, int destination)
        {
            var n = graph.GetLength(0);
            var done = new bool[n];
            var dist = new int[n];
            var queue = new Queue<int>();

            done[departure] = true;
            dist[departure] = 0;
            queue.Enqueue(departure);

            while (queue.Count > 0)
            {
                var r = queue.Dequeue();
                if (r == destination) return dist[r];
                for (int i = 0; i < n; i++)
                {
                    if (graph[r, i] && !done[i])
                    {
                        done[i] = true;
                        dist[i] = dist[r] + 1;
                        queue.Enqueue(i);
                    }
                }
            }
            return -1;
        }
    }
}

