            for(int i = 0; i < n; ++i)
            {
                g[i] = new List<int>();
            }
            for(int i=0;i<m;++i)
            {
                szarr = Console.ReadLine().Split(' ');
                int v0 = int.Parse(szarr[0]);
                int v1 = int.Parse(szarr[1]);

                g[v0].Add(v1);
                g[v1].Add(v0);
            }
            int q = int.Parse(Console.ReadLine());

            int[] color = new int[n];
            int[] d = new int[n];
            var queue = new Queue<int>();

            for (int i=0;i<q;++i)
            {
                szarr = Console.ReadLine().Split(' ');
                int v0 = int.Parse(szarr[0]);
                int v1 = int.Parse(szarr[1]);
                // ２人はフレンド？
                for (int j = 0; j < color.Length; ++j) { color[j] = WHITE; }
                for (int j = 0; j < d.Length; ++j) { d[j] = -1; }
                queue.Clear();
                BFS(v0, color, d, queue, g);

                if(d[v1] >= 0)
                {
                    Console.WriteLine("yes");
                }
                else
                {
                    Console.WriteLine("no");
                }
            }


        }
        static void BFS(int s, int[] color, int[] d, Queue<int> q, List<int>[] g)
        {
            color[s] = GRAY;
            d[s] = 0;
            q.Enqueue(s);
            while(q.Count >= 1)
            {
                int u = q.Dequeue();
                for(int v = 0;v<g[u].Count;++v)
                {
                    if(color[v] == WHITE)
                    {
                        color[v] = GRAY;
                        d[v] = d[u] + 1;
                        q.Enqueue(v);
                    }
                }
                color[u] = s;
            }
         }
    }

