class SNS
  def initialize(n)
    @group_tbl = []
    @priority = []
    n.times{|i|
      @group_tbl[i] = i
      @priority[i] = 0
    }
  end

  def setGroup(i, j)
    ii = theGroup(i)
    jj = theGroup(j)
    if @priority[ii] > @priority[jj] then
      @group_tbl[jj] = ii
    else
      @group_tbl[ii] = jj
      @priority[jj] += 1 if @priority[ii] == @priority[jj]
    end
  end

  def isSameGroup(i, j)
    return theGroup(i) == theGroup(j)
  end

  def theGroup(i)
    @group_tbl[i] = theGroup(@group_tbl[i]) if i != @group_tbl[i]
    return @group_tbl[i]
  end
end
