let split str delim =
  let open String in
  let rec doit s acc =
    match
      try Some (rindex s delim) with _ -> None
    with
    | None -> s :: acc
    | Some i ->
      let s1 = sub s 0 i in
      doit s1 (sub s (i + 1) (length s - length s1 - 1) :: acc)
  in doit str []

let read_ints () = List.map int_of_string (split (read_line ()) ' ')

let dfs g n =
  let v = Array.make n (-1) in
  let rec doit i =
    if i < n then (if v.(i) = (-1) then dudu i i; doit (i + 1))
  and dudu i j =
    v.(i) <- j;
    wa j g.(i)
  and wa j = function
    | [] -> ()
    | hd :: tl when v.(hd) = (-1) -> (dudu hd j; wa j tl)
    | _ :: tl -> wa j tl
  in doit 0;
  v

let solve n m =
  let g = Array.make n [] in
  let rec read i =
    if i < m then
      begin match read_ints () with
      | [s;t] ->
        g.(s) <- t :: g.(s);
        g.(t) <- s :: g.(t);
        read (i + 1)
      | _ -> exit 1
      end in
  read 0;
  let v = dfs g n in
  let q = read_int () in
  let rec read_q i =
    if i < q then
