NOT_FOUND = 0
ENQUEUED = 1
FOUND = 2

def dfs(graph, start, end):
    stack = [start]
    status = [NOT_FOUND] * len(graph)

    def loop(stack, status, graph, start, end):
        debug("-------------------")
        debug(stack)
        debug(graph)
        if len(stack) == 0:
            debug(stack)
            return False

        v = stack.pop()
        status[v] = FOUND
        if v == end:
            return True

        edges = graph[v]
        if len(edges) != 0:
            stack.append(v)
            e = edges.pop(0)
            if e == end:
                return True
            if status[e] == NOT_FOUND:
                stack.append(e)
                status[e] = ENQUEUED

        return loop(stack, status, graph, start, end)

    return loop(stack, status, copy.deepcopy(graph), start, end)

