    debug(graph)
    if start == target:
        return True

    queue = []
    status = [NOT_FOUND] * len(graph)
    queue.append(start)

    while len(queue) != 0:
        node = queue.pop(0)
        status[node] = FOUND
        edges = graph[node]
        for e in edges:
            if e == target:
                return True
            if status[e] == NOT_FOUND:
                status[e] = ENQUEUED
                queue.append(e)

    return False

