        while let Some(idx) = que.pop_back() {
            for i in nodes[idx].iter() {
                if color[*i] == 0 {
                    color[*i] = color[idx];
                    que.push_back(*i);
                }
            }
        }
    }


    let q: usize = sc.read();
    for _ in 0..q {
        let s: usize = sc.read();
        let t: usize = sc.read();
        if color[s] == color[t] {
