fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let n: usize = iterator.next().unwrap().parse().unwrap();
    let m: usize = iterator.next().unwrap().parse().unwrap();

    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    for _ in 0..m {
        let s: usize = iterator.next().unwrap().parse().unwrap();
        let t: usize = iterator.next().unwrap().parse().unwrap();
        graph[s].push(t);
        graph[t].push(s);
    }

    let mut colors: Vec<usize> = vec![0; n];
    let mut color = 1;
    for i in 0..n {
        if colors[i] != 0 {
            continue;
        }

        // bfs
        // let mut queue: VecDeque<usize> = VecDeque::new();
        // queue.push_back(i);
        // while !queue.is_empty() {
        //     let node = queue.pop_front().unwrap();
        //     colors[node] = color;
        //     for linked in graph[node].iter() {
        //         if colors[*linked] == 0 {
        //             queue.push_back(*linked);
        //         }
        //     }
        // }

        // dfs
        let mut stack: Vec<usize> = Vec::new();
        stack.push(i);
        while !stack.is_empty() {
            let node = stack.pop().unwrap();
            colors[node] = color;
            for linked in graph[node].iter() {
                if colors[*linked] == 0 {
                    stack.push(*linked);
                }
            }
        }

        color += 1;
    }

    let mut result = String::new();

    let q: usize = iterator.next().unwrap().parse().unwrap();
    for _ in 0..q {
        let s: usize = iterator.next().unwrap().parse().unwrap();
        let t: usize = iterator.next().unwrap().parse().unwrap();
        if colors[s] == colors[t] {
            result.push_str("yes\n");
        } else {
            result.push_str("no\n");
        }
    }

    return result.trim().to_string();
}

use std::io;
use std::io::BufRead;

struct Graph {
    n: usize,
    adj: Vec<Vec<usize>>,
}

fn read_graph() -> Graph {
    let stdin = io::stdin();
    let lock = stdin.lock();
    let mut lines = lock.lines();

    let nm: Vec<_> = lines
        .next()
        .unwrap()
        .unwrap()
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let n = nm[0];
    let m = nm[1];
    let mut adj = vec![vec![]; n];

    for _ in 0..m {
        let parsed: Vec<usize> = lines
            .next()
            .unwrap()
            .unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        let i = parsed[0];
        let j = parsed[1];

        adj[i].push(j);
        adj[j].push(i);
    }

    Graph { n, adj }
}

fn dfs(g: &Graph, d: &mut Vec<Option<usize>>, i: usize, root: usize) {
    d[i] = Some(root);
    for &next_i in g.adj[i].iter() {
        if d[next_i] == None {
            dfs(g, d, next_i, root);
        }
    }
}

fn main() {
    let graph = read_graph();

    let mut d = vec![None; graph.n];

    for i in 0..(graph.n) {
        if d[i] == None {
